(window.STORIES=window.STORIES||[]).push(...[{"n": 191, "l": "الجزء 165 | احداث السنه الثامنه من الهجرة | قصص بعض من أمر رسول الله بقتلهم", "u": "https://www.facebook.com/groups/710210019782034/permalink/836543230482045/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وخمسة_وستون\n#أحداث_السنة_الثامنة_من_الهجرة\n#قصص_بعض_مَن_أَمر_رسول_الله_بقتلهم\nاتكلمنا المرة إللي فاتت عن دخول رسول الله ﷺ مكة وشوفنا إزاي دخل مكة بجيشه من أربع جهات،\nوقلنا إن رسول الله ﷺ نزل في منطقة الحَجُون ونَصب له الصحابة قُبّة وهي حاجة زي الخيمة كده عشان يريّح فيها،\nومنطقة الحجون هي منطقة فيها مقابر أهل مكة وقريبة من شعب أبي طالب إللي اتحاصر فيه المسلمين ثلاث سنوات،\nوكان رسول الله ﷺ معاه زوجتاه أم سلمة وميمونة بنت الحارث رضي الله عنهما.\n☆بالمناسبة يا جماعة في معلومة مشهورة بين الناس وهي  إن رسول الله ﷺ قال للصحابة:\n\"انصبوا لي خيمة عند قبر خديجة\"\nوالكلام ده غير صحيح إطلاقا\nلأن مفيش أي حديث صحيح ولا حتى ضعيف بيدل على إن رسول الله ﷺ أمر بنصْب خيمته بالحجون عشان قبر خديجة، ودي حاجة عشان نعرفها لازم يكون رسول الله ﷺ قالها صريحة مش الناس تقعد تخمن وتستنتج\nومنطقة الحَجون أصلا فيها مَدفن لأهل مكة كلهم بيدفِنُوا فيه موتاهم يعني مش خديجة رضي الله عنها بس هي إللي مدفونة فيه،\nوقبر خديجة مكنش له علامة مميزة عن باقي القبور عشان يعرفوه يعني وينصبوا عنده الخيمة،\nده غير كده أصلا رسول الله ﷺ قبل ما يدخل مكة كان قال للصحابة عن المكان إللي هينزل يقعد فيه ووصفه بوصف بعيد كل البُعد عن إنه يكون قبر خديجة، قال ﷺ:\n\" مَنْزِلُنَا غَدًا إِنْ شَاءَ اللَّهُ، بِخَيْفِ بَنِي كِنَانَةَ، حَيْثُ تَقَاسَمُوا عَلَى الكُفْرِ\"\nيعني المكان إللي نزل فيه رسول الله ﷺ له معنى،\nفي المكان إللي ذكره ده كان الكفار تحالفوا على مقاطعة بني هاشم ومحاصرتهم في شِعب أبي طالب وقالوا إنهم مش هيفكوا المقاطعة والحصار ده غير لما بني هاشم يسلّموا لهم رسول الله ﷺ عشان يقتلوه،\nفكأن رسول الله ﷺ بيقولهم أنا هنا أهه ومحدش منكم استطاع إنه يمسني بسوء ودخلت مكة فاتحا ونصرني الله عليكم وكل التحالفات بتاعتكم ولا كان لها أي لازمة والناس إللي اتحالفت ضدي هلكوا وأنا إللي بقيت\nالمهم،\nلما رسول الله ﷺ نزل بالحجون وريّح فيها شوية، سأله أسامة بن زيد إللي كان راكب وراه على الناقة بتاعته ولما نزل في الحَجُون نزل معاه أسامة، قال له:\n\" أين تنزل غدًا يا رسول الله\"\nيعني هتبات فين بكرة؛ لأن المفروض إن رسول الله ﷺ له بيت في مكة وهو بيت خديجة رضي الله عنها إللي رسول الله ﷺ كان عايش فيه قبل الهجرة،\nفقال له رسول الله ﷺ:\n\"وهل ترك لنا عَقِيل من رِباعٍ أو دُور\"\nعقيل ده ابن أبي طالب وأخو علي، فلما هاجر رسول الله ﷺ واستقر في المدينة باع عقيل بيت رسول الله ﷺ وأخذ ثمنه، فدلوقتي رسول الله ﷺ مبقاش عنده بيت في مكة، ورفض إنه ينزل في بيت أحد،\nوالصحابة قعدوا يستريحوا شوية همّ كمان بعد طول السفر والتعب قبل ما يعطيهم رسول الله ﷺ مهمات جديدة.\nبنو خزاعة كانوا عايزين يثأروا من بني بكر إللي نقضوا العهد واعتدوا عليهم وقتلوا منهم رجال عند الحرم،\nفطلبوا الإذن من رسول الله ﷺ إنه يسمح لهم بغزو بني بكر، فأَذِن لهم رسول الله ﷺ ولكنه حدد لهم فترة زمنية معينة،\nيعني الغزو هيبدأ من ساعة ما طلبوا لحد وقت العصر فقط وبعدها يوقفوا القتال،\nقال رسول الله ﷺ:\n\"كُفّوا السلاح إلا خُزاعَة من بني بكر\"\nيعني إللي لهم إذن بالقتال هم:\n◇أولا: بنو خزاعة عشان يأخذوا ثأرهم من بني بكر،\nولما جاء وقت العصر أمرهم إنهم يوقفوا القتال خلاص ومحدش يُقاتل مرة تانية\n◇ثانيا:\nالناس إللي رسول الله ﷺ أمر بقتلهم ولو كانوا متعلقين بأستار الكعبة.\nكنا قلنا المرة إللي فاتت إن رسول الله ﷺ أهْدر دم مجموعة من كفار مكة، يعني أمر بقتل مجموعة من الأشخاص من أهل مكة حتى لو كانوا متعلقين بأستار الكعبة،\nوقلنا إنهم كانوا أربعة رجال وامرأتين، وفي رواية تانية كانوا أحد عشر رجل وأربعة نساء، يعني كلهم خمسة عشر إنسان،\nوعلى فكرة معظمهم أسلموا ولم يُقتل منهم غير أربعة فقط\nواختلف العلماء في السبب إللي خلى رسول الله ﷺ يهدر دمهم،\nيعني هم عملوا حاجات لا تُغتفر، لكن إيه هي بالضبط؟ \nالعلماء مختلفين فيها، فهقول لكم أشهر أقوال العلماء في بعض قصص الناس دي،\n◇أول ثلاثة:\nعبد الله بن خَطل ومغنيتان كان يملكهما،\nعبد الله بن خَطل ده كان اسمه «عبد العزى» فأسلم وهاجر للمدينة فسماه رسول الله ﷺ ﷺ عبد الله،\nوبعثه رسول الله ﷺ في مهمة أخذ الصدقة وأرسل معه  رجلا من الأنصار وكان معاه مولى له بيخدمه والمولى ده كان مسلما، فنزل عبد الله بن خطل في مكان يستريح وأمر المَوْلى إنه يذبح له شاة ويصنع له طعام،\nونام عبد الله بن خطل لحد ما المولى يخلص صُنع الطعام،\nفلما صحي من النوم مَلقاش المولى بتاعه عمل أكل،\nفغضب منه فراح قتله وارتد بعدها ورجع لمكة، \nوهو كان شاعر فقعد بيهجو رسول الله ﷺ والمغنيتين دول كانوا بيغنوا شعر الهجاء ده يعني بيشتموا رسول الله ﷺ في الأغاني إللي بيقولوها\nيعني قتل نفس بغير حق وارتد عن الإسلام وشتم رسول الله ﷺ والثلاث جرائم دول حدّهم في الإسلام القتل\nفلما شاف خيل المسلمين خاف وهرب نحو الكعبة وتعلّق بأستارها عشان ينجو من القتل.\n☆ده بدل ما يروح لرسول الله ﷺ يطلب الأمان ويعتذر عن إللي عمله\nفشافوه المسلمون وقالوا لرسول الله ﷺ إن عبد الله بن خطل متعلق بأستار الكعبة، \nفأمرهم رسول الله ﷺ بقتله، أما المغنيتين فواحدة منهم قُتلت والتانية أسلمت وحَسُن إسلامُها.\n◇في هنا سؤال عن قتل ابن خَطل وهو متعلق بأستار الكعبة، يعني هو في بلد الله الحرام وكمان متعلق بأستار الكعبة، فإزاي رسول الله ﷺ يأمر بقتل ناس في بلد الله الحرام\nإللي يجاوبنا على السؤال ده رسول الله ﷺ نفسه\nبعد ما رسول الله ﷺ أمر خزاعة إنهم يوقفوا قتال خلاص، تاني يوم الفتح رجل من خزاعة قابل رجل من بني بكر فقتله،\nفوصل الأمر لرسول الله ﷺ فخرج في الناس وخطب فيهم وقال:\n\"إن مكة حرَّمها الله يوم خلق السماوات والأرض، ولم يُحرمها الناس،\nفلا يَحلُّ لامرئ يؤمن بالله واليوم الآخر أن يَسفِك بها دمًا، ولا يعضُد بها شجرة،\nفإن أحدٌ ترخّص بقتال رسول الله ﷺ فقولوا:\nإن الله أَذِن لرسوله ولم يُؤذن لكم، وإنما أُذِن لي ساعة من نهار، وقد عادت حرمتها اليوم كحُرْمَتها بالأمس، فليُبلّغ الشاهد الغائب\"\nيعني إيه الكلام ده\nيعني رسول الله ﷺ بيقول للناس إن ربنا هو إللي جعل مكة بلد حرام لا يحل فيه القتل ولا الصيد ولا قطع الأشجار،\nمش الناس هم إللي خلوها بلد حرام وحرموها زي ما حرموا حاجات في الجاهلية من عند أنفسهم زي البَحِيرة و الحَام إللي اتكلمنا عنهم في الجزء الثالث من السيرة لو تفتكروا\nوربنا كاتب في اللوح المحفوظ من قَبل خلق السماوات والأرض أصلا إن مكة هي أرض الله الحرام،\nوكمان كُتبَ تحريمها مرة أخرى يوم ما خُلقت السماوات والأرض، كنوع من زيادة التخصيص،\nولما جاء زمن إبراهيم عليه السلام نزل التشريع بقى في الأرض بحُرمة بيت الله الحرام\nفالخُلاصة إن ربنا هو إللي جعل مكة بلد حرام لا يُقتل فيها إنسان ولا يُقطع منها شجر، فتحريمها ثابت بالشرع وهي من حرمات الله،\nوبعدين رسول الله ﷺ قال لهم لو حد قال: ما هو رسول الله ﷺ قاتل في مكة وأمر بقتل بعض الناس فقولوا له إن ربنا أحل مكة لرسوله مدة زمنية معينة 《 ساعة من النهار》 وهي الفترة من طلوع شمس يوم فتح مكة لحد العصر،\nودي حاجة ربنا أحلّها لرسول الله ﷺ ولم يُحِلُّها لغيره من الناس،\nومجرد ما الوقت المسموح خلص فهي خلاص رجعت لحُرمتها إللي ربنا حرّمها قبل كده، فلا يحل فيها القتل ولا القتال\n《الحديث إللي قلناه ده\n في البخاري وإللي عايز يتوسع في الشرح هيلاقي الرابط في التعليقات\n》\nفرسول الله ﷺ لما أمر بقتل عبد الله بن خَطَل وغيره حتى لو متعلقين بأستار الكعبة كان قتلهم في الوقت إللي ربنا سمح له به\n◇أما الرابع إللي رسول الله ﷺ أمر بقتله فهو : \nمَقِيسُ بن صَبَابَة، ومَقيس ده كان أسلم هو كمان وكان له أخ اسمه هشام بن صبابة، هشام كان في غزوة ذي قَرَد فواحد من الأنصار فكّره من الأعداء فقتله بالغلط،\nوإللي بيقتل مسلم خطأ بيدفع الدِّيَة بتاعته، فتم دفع الدِّيَة لمقيس بن صبابة،\nوبعد ما أخذ مقيس الدِّيَة قتل الأنصاري وارتد ورجع لقريش فأهدر رسول الله ﷺ دمه،\nولما جاء جيش المسلمين مكة لقوه في السوق فقتلوه، وإللي قتله رجل من قومه\n◇الخامس:\nعكرمة بن أبي جهل، وطبعا من اسمه واضح هو مين عكرمة واحنا عارفين عدائه لرسول الله ﷺ\nكنا قلنا إن عكرمة بن أبي جهل هرب بعد ما فشلت المحاولة إللي عملوها في مقاومتهم لجيش المسلمين وهزمهم خالد بن الوليد رضي الله عنه،\nفلما هرب عكرمة توجه إلى البحر وركب سفينة في البحر، فجاءت ريح شديدة وهاج البحر وبقوا خلاص هيهلكوا كلهم،\nفقال الناس إللي في السفينة لبعض :\n\"أخلِصوا فإنَّ آلهتَكم لا تُغْني عنكم شيئًا ها هنا\"\nيعني ادعوا ربنا بدون ما تشركوا معاه أي إله تاني لأن هو الوحيد إللي هينجيكم والآلهة لن تنفع بشيء،\nكل ده وعكرمة شايف الموقف، فقال في نفسه:\n\" واللهِ لئِنْ لم يُنجِني مِن البحرِ إلَّا الإخلاص فكذلكَ لا يُنجِيني في البَرِّ غيرُه\"\nيعني لو توحيد ربنا وإفراده بالعبادة هو إللي هينجيني في البحر، فمفيش حاجة هتنجيني في البر على الأرض غيره \nوهنا بقى دخل الإيمان في قلب عكرمة، ودعا وقال:\n\"اللَّهمَّ إنَّ لكَ علَيَّ عهدًا إن أنتَ عافَيْتَني ممَّا أنا فيه أنْ آتِيَ محمَّدًا ﷺ حتَّى أضَعَ يَدي في يدِه فلَأجِدَنَّه عفُوًّا كريمًا\"\nيعني بيقول يارب عهد عليّ لو انت نجتني من الغرق أنا هرجع لمحمد ﷺ وأبايعه على الإسلام وهو هيعفو عني ويصفح زي ما بيعفو عن كل واحد بيأتيه تائب وراغب في الإسلام،\nوفعلا جاء عكرمة وأسلم عند رسول الله ﷺ وفرح رسول الله ﷺ بإسلام عكرمة، وحسُن إسلام عكرمة وكان يجاهد في سبيل ويُكثر من عمل الصالحات لحد ما قُتل شهيدا في معركة اليرموك رضي الله عنه.\n☆وهنا في حديث مشهور بين الناس ولكنه حديث مكذوب موضوع لا يصح عن رسول الله ﷺ \nالحديث  بيقول إن رسول الله ﷺ قال للصحابة قبل ما يأتي عكرمة يعلن إسلامه:\n\"يأتيكُم عِكرمةُ بنُ أبى جهلٍ مؤمنًا مهاجِرًا ، فلا تسبُّوا أباهُ ، فإنَّ سبَّ الميِّتِ يؤذي الحيَّ ، و لا يبلُغُ الميِّتَ ، \nفلمَّا بلغ بابَ رسولِ اللهِ استبشَر ﷺ و وثبَ لهُ رسولُ اللهِ ﷺ  قائمًا علَى رِجلَيهِ ، فرِحًا بقدومِه\"\nفالحديث ده غير صحيح يا جماعة، فخدوا بالكم قبل ما تنشروا أي حديث تبقوا عارفين هو صحيح ولّا لأ\n◇الرجل السادس إللي أهدر رسول الله ﷺ دمه:\nوحْشِي بن حرب قاتل حمزة، وكان الصحابة حريصين إنهم يقتلوه، ولكن وحشي كان هرب من مكة إلى الطائف لما عرف إن جيش المسلمين داخل مكة خلاص،\nوبعدين بقى لما جاء لرسول الله ﷺ وفد من الطائف عشان يعلنوا إسلامهم ساعتها ملقاش له أي مكان يلجأ إليه فراح لرسول الله ﷺ عشان يُسلم،\nوهو إللي قتل مسيلمة الكذاب مُدعي النبوة بنفس الحربة إللي قتل بها حمزة وكان بيقول : قتلتُ خير الناس وشر الناس،\nخير الناس حمزة وشر الناس مُسَيلمة الكذاب.\n◇الرجل السابع:\nعبد الله بن سعد بن أبي السَّرْح، وهو أخو عثمان بن عفان من الرضاعة وكان أسلم وكمان من كُتّاب الوحي، لكن أزلّه الشيطان وارتد عن الإسلام ورجع لمكة وكان بيشتم رسول الله ﷺ،\nفلما جاء فتح مكة وكان رسول الله ﷺ أهدر دمه،\nالتجأ عبد الله بن سعد لبيت عثمان بن عفان وكان عايز يبايع رسول الله ﷺ على الإسلام بس كان خايف،\nفجاء به عثمان بن عفان لرسول الله ﷺ و أَوْقَفَهُ أمام رسول الله ﷺ وقال له عثمان:\n \"يَا نَبِيَّ اللَّهِ بَايِعْ عَبْدَ اللَّهِ\"\nيعني خذ منه البيعة على الإسلام لأنه عايز يتوب،\nفرفع رسول الله ﷺ رأسه فنظر إليه فشاف إنه عبد الله بن سعد وكان جاي متخفّي عشان محدش يشوفه ويقتله،\nفرسول الله ﷺ امتنع عن مبايعته،\nفعثمان رضي الله عنه أعاد الكلام على رسول الله ﷺ :\n\"يَا نَبِيَّ اللَّهِ بَايِعْ عَبْدَ اللَّهِ\"\nورسول الله ﷺ ينظر إليه ويرفض إنه يبايعه، الموقف اتكرر ثلاث مرات، وبعد المرة الثالثة بايعه رسول الله ﷺ على الإسلام،\nوخرج عبد الله بن سعد من عند رسول الله ﷺ، فقال رسول الله ﷺ لأصحابه:\n\"أَمَا كَانَ فِيكُمْ رَجُلٌ رَشِيدٌ يَقُومُ إِلَى هَذَا حَيْثُ رَآنِي كَفَفْتُ يَدِي عَنْ بَيْعَتِهِ فَيَقْتُلُهُ\"\nيعني مفيش واحد فيكم عنده عقل حكيم شافني امتنعت عن مبايعة عبد الله فيقوم يقتله،\nوكان في واحد وسط الصحابة الموجودين كان نذر إنه يقتل عبد الله بن سعد بن أبي السرح،\nفقال له رسول الله ﷺ ليه مقتلتهوش ووفيت بنذرك،\nفهنا الصحابة قالوا:\n\"مَا نَدْرِي يَا رَسُولَ اللَّهِ مَا فِي نَفْسِكَ أَلَا أَوْمَأْتَ إِلَيْنَا بِعَيْنِكَ\"\nيعني احنا مش عارفين إيه إللي انت بتفكر فيه يا رسول الله، لو كنت بس غمزت لنا أو بصيت لنا أو عملت أي حركة نفهم بيها كنا قتلناه على طول،\nفقال لهم رسول الله ﷺ:\n\"إِنَّهُ لَا يَنْبَغِي لِنَبِيٍّ أَنْ تَكُونَ لَهُ خَائِنَةُ الْأَعْيُن\"\nخائنةُ الأعيُنِ معناها:\nإن الإنسان يُخفي في قلبه غير إللي بيظهره للناس أو يُظهِرَ منه للنَّاسِ،\nيعني رسول الله ﷺ دلوقتي ظاهره إنه أعطى الأمان وقَبِل من عبد الله بن سعد بن أبي السرح الإسلام،\nفمينفعش يلتفت لحد من أصحابه أو يشير لهم بأي إشارة تدل على عكس الأمان إللي ظهر من رسول الله ﷺ،\nفرسول الله ﷺ وكل الأنبياء مُنزّهُون عن الخيانة والغدر\n☆طبعا لازم هيطلع لنا هنا سؤال، هو ليه رسول الله ﷺ مكنش راضي يقبل بيعة عبد الله بن سعد بن أبي السرح وكان عايز الصحابة يقتلوه\nشوفوا يا جماعة عبد الله بن سعد بن أبي السرح عمل حاجتين يستحق عليهم القتل:\n◇الردة: لأن المرتد كافر وحدّه القتل زي ما رسول الله ﷺ قال:\n\" مَنْ بَدّل دِينَه فاقتلُوه\"\nوالقتل للسبب ده هو حق لله تعالى، يسقط الحق ده بتوبة المرتد ورجوعه إلى الإسلام\nفلما جاء عبد الله بن سعد بن أبي السرح وأسلم وتاب سقط عنه حد الردة، واتبقى له السبب التاني وهو:\n◇ إنه كان يَسُب رسول الله ﷺ، واحنا عارفين إن إللي يسُب ويشتم رسول الله ﷺ حدّه القتل حتى لو كان مسلم وتاب إلا أن يعفوا عنه رسول الله ﷺ،\nفهنا من حق رسول الله ﷺ إنه يعفو أو لا يعفو، فاختار رسول الله ﷺ إنه ميعفوش عن ابن أبي السرح،\nده غير إن في 《روايات ضعيفة》 بتقول إن عبد الله بن سعد بن أبي السرح افترى على رسول الله ﷺ الكذب وقال عنه إنه كان بيُبدّل في القرآن بحسب إللي بيُمليه عليه ابن أبي السرح،\nيعني مثلا رسول الله ﷺ كان يقول لعبد الله بن سعد اكتب : ( عليم حليم ) فيقول ابن أبي السرح لرسول الله ﷺ:\nأو أكتب : ( عزيز حكيم )؟ \nيعني ولّا اكتب عزيز حكيم بدل عليم حليم فيقول له رسول الله ﷺ : كلاهما سواء،\nيعني همّ الاتنين زي بعض،\nفلو فعلا الروايات دي فيها شيء من الصحة وإن عبد الله بن  سعد افترى الكذب ده على رسول الله ﷺ فمن حق رسول الله ﷺبصراحة إنه ميعفوش عنه\nده كده بيضل الناس ويبعدهم عن الدين وبيتهم رسول الله ﷺ بإنه بيكذب على ربنا،\nتخيلوا إن لو حد فينا شاف واحد بيدلّس على الناس وبيقول كلام غلط عن الإسلام هنبقى متضايقين إزاي،\nفما بالكم بقى برسول الله ﷺ إللي هو أغير على الدين من أي حد فينا\nفلما شَفع عثمان لرسول الله ﷺ في عبد الله بن سعد بن أبي السرح، رضي رسول الله ﷺ بشفاعة عثمان وعفا عن عبد الله بن سعد بن أبي السرح،\nورسول الله ﷺ كان يحب عثمان بن عفان رضي الله عنه وهو كان تزوج ابنتين لرسول الله ﷺ، فتخيلوا حب رسول الله ﷺ لعثمان إللي خلّاه يقبل بشفاعته لواحد زي عبد الله بن سعد بن أبي السرح\nعبد الله بن سعد بن أبي السرح ده بعد إسلامه ومبايعته برسول الله ﷺ حَسُن إسلامه وجاهد في سبيل الله وفتح الله على يَديه أفريقيا وحضر معركة ذات الصواري، \nوكان دعا بأن يُختم عمره بالصلاة، وفعلا في يوم بعد ما صلى الصبح بعد ما سلّم التسليمة الثانية مات، وكان موته في سنة ست وثلاثين للهجرة رحمه الله ورضي الله عنه.\n《إللي عايز يعرف معلومات أكتر عن قصة عبد الله بن سعد بن أبي السرح هيلاقي الرابط في التعليقات من موقع الإسلام سؤال وجواب، أنا بجيب لكم المختصر المفيد من الكلام بس\n》\n☆في هنا بقى قصة تانية لواحد نصراني من بني النّجار منعرفش اسمه كان أسلم في عهد رسول الله ﷺ وكان هو كمان من كُتّاب الوحي، وكان قرأ البقرة وآل عمران،\nوبعد كده ارتد، ولعل ناس كتير بتخلط بين قصته وبين قصة عبد الله بن سعد بن أبي السرح، لكن هم الاتنين شخصين مختلفين عن بعض تماما،\nالرجل النصراني ده كان بيقول بعد ما ارتد:\n\"ما يَدْرِي مُحَمَّدٌ إلَّا ما كَتَبْتُ له\"\nيعني أنا إللي كنت بملّي محمد ﷺ القرآن، وطبعا الكلام ده كذب، فأماته الله فدفنه أصحابه، يعني حفروا في الأرض ودفنوه وغطوا عليه بالتراب، وتاني يوم بعد ما دفنوه لقوه برة القبر قد لَفَظَته الأرض\nفَقالوا:\nهذا فِعْلُ مُحَمَّدٍ وأَصْحَابِهِ لَمَّا هَرَبَ منهمْ، نَبَشُوا عن صَاحِبِنَا فألْقَوْهُ\nيعني اتهموا رسول الله ﷺ والصحابة إنهم إللي طلعوا جثته من القبر ورموها كده عشان هو هرب منهم فبينتقموا منه،\nفحفروا له قبر تاني والمرة دي بقى أَعمَقُوا الحفرة وخلّوها غويطة،\nفتاني يوم لقوه مرة تانية برة القبر بتاعه\nفقالوا:\n\"هذا فِعْلُ مُحَمَّدٍ وأَصْحَابِهِ، نَبَشُوا عن صَاحِبِنَا لَمَّا هَرَبَ منهمْ فألْقَوْهُ\"\nفحفروا له وأعمقوا في الأرض جدا على قَدر ما استطاعوا،\nفلما جه اليوم التالي لقوا جثته برة القبر وقد لَفَظَتْها الأرض\nفعرفوا إن إللي عمل كده مش حد من البشر ولكنه رب البشر فرموه بقى ومشيوا،\nودي عاقبة إللي يكذب على رسول الله ﷺ\n《قصة الرجل النصراني دي صحيحة وموجودة في صحيح البخاري》\nكده احنا عرفنا مصير سبعة من إللي رسول الله ﷺ أهدر دمهم، الباقيين هنتكلم عنهم واحنا بنشوف رسول الله ﷺ عمل إيه بعد ما استريح شوية في خيمته في الحجون،\nعمل إيه بقى رسول الله ﷺ \nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 192, "l": "الجزء 166 | احداث السنه الثامنه من الهجرة | اهل مكه الطلقاء", "u": "https://www.facebook.com/groups/710210019782034/permalink/836543427148692/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وستة_وستون\n#أحداث_السنة_الثامنة_من_الهجرة\n#أهل_مكة_الطُّلَقَاء\nاتكلمنا المرة إللي فاتت عن بعض الناس إللي رسول الله ﷺ أمر بقتلهم، وشوفنا إللي قُتلوا وشوفنا إللي تاب منهم وأسلم وعفا عنهم رسول الله ﷺ،\nآخر واحد من الأربعة إللي قُتلوا هو الحُوَيْرِث بن نُقَيد،\nده كان بيهجو رسول الله ﷺ وبيشتمه وكان بيؤذيه كتير لما كان في مكة، فأهدر رسول الله ﷺ دمه وقتله علي بن أبي طالب رضي الله عنه يوم الفتح،\nوكان في اتنين من الرجلين إللي رسول الله ﷺ أهدر دمهم هربوا والْتَجأوا بأم هانئ أخت علي بن أبي طالب،\nفأجارتهم أم هانئ وراحت لرسول الله ﷺ وكان ساعتها وقت الضحى لسه وكان ﷺ بيغتسل وكانت ابنته السيدة فاطمة تستره بثوبه ﷺ،\nفلما جاءت أم هانِئ استأذنت ودخلت على رسول الله ﷺ، فسأل رسول الله ﷺ مين إللي جاءت دي،\nفقالت: أم هانئ، فرحب بها رسول الله ﷺ ولما انتهى من غُسله الْتَحَف برداء وصلى الضحى ثمانِ ركعات،\nولما انتهى من الصلاة قالت له إنها أجارت رجلين من إللي رسول الله ﷺ أهدر دمهم،\nيعني هم دلوقتي في حماياتها ولكن علي بن أبي طالب مش معترف بحمايتها للرجلين الكافرين دول وعايز يقتلهم،\nفرسول الله ﷺ قال لها:\n\"قد أَجَرْنا من أجرتِ يا أم هانئ\"\nيعني خلاص احنا كمان هنحمي إللي انتِ عايزة تحميهم ومش هنقتلهم\nخرج رسول الله ﷺ وركب دابته وقام معاه جَمْع كبير من المهاجرين والأنصار وأحاطوا به وتقدم رسول الله ﷺ واتجه للكعبة عشان يطوف حولها،\nوخرجت قريش من بيوتها عشان يشوفوا رسول الله ﷺ وإللي هيعمله،\nيعني حظر التجول إللي حصل في مكة كان مدته كم ساعة بس عشان قريش متفكرش في المقاومة، فلما خلاص الوضع بقى مستقر خرج الناس من بيوتهم،\nوصل رسول الله ﷺ للكعبة إللي كانت خلال السنين إللي فاتت دي كلها كان في حولها ثلاثمائة وستون صنمًا (360) \nطبعا ده غير هُبل الصنم الأعظم عندهم،\nوكان رسول الله ﷺ خلال السنين دي لما كان بيصلي أو يطوف حول الكعبة كانت الأصنام دي موجودة، \nفي اللحظة دي بقى أمر رسول الله ﷺ بتكسير الأصنام إللي حول الكعبة وهو نفسه كان بيكسرها بقوس أو عصا كانت في إيده وهو بيطوف حول الكعبة، يعني كان يشير بالقوس للصنم وهو يقول :\n\"جَاءَ الحَقُّ وَزَهَقَ البَاطِلُ، إِنَّ البَاطِلَ كَانَ زَهُوقًا\"\n\"جَاءَ الحَقُّ وما يبدئُ البَاطِلُ وما يُعِيد\"\nوقبل ما طرف القوس يلمس الصنم كان الصنم يقع على ظهره أو على وجهه ويتكسر، \nكل ده وأهل مكة شايفين الآلهة إللي كانوا بيعبدوها همّ وآباؤهم مئات السنين بتتكسر واحد ورا التاني\nالموقف رهيب\nالرجل إللي قعد يدعوهم للإسلام والإيمان بالله وحده وترك عبادة الأصنام ثلاثة عشرة سنة وكذبوه واتهموه بالسحر وإنه شاعر وعذبوا أصحابه وقتلوا منهم، وطاردوه وآذوه عشان الأصنام إللي كانوا بيعبدوها؛ رجع لهم تاني بعد ثماني سنوات من خروجه من مكة،\nوهو إللي بيكسرها بإيده وكلهم شايفين ومحدش فيهم قادر يعمل له أي حاجة\nواتكسرت تماماً كل معنويات أهل مكة، \nوالمشركين كانوا مفكرين إن الآلهة بتاعتهم دي مش هتسكت وهتصيب رسول الله ﷺ و المسلمين معاه بالأذى،\nلكن محصلش أي حاجة وظهرت الحقيقة واضحة أمام أعْيُن المشركين وإنهم كانوا في ضلال مبين كل  السنوات إللي فاتت دي وآلهتهم منفعتهمش بشيء\n\"فَمَا أَغْنَتْ عَنْهُمْ آلِهَتُهُمُ الَّتِي يَدْعُونَ مِن دُونِ اللَّهِ مِن شَيْءٍ لَّمَّا جَاءَ أَمْرُ رَبِّكَ\"\n☆رسول الله ﷺ خلال السنين إللي فاتت دي كلها مفكرش يكسر ولو صنم واحد، عارفين ليه\nلأن رسول الله ﷺ كان عنده فقه للواقع، تخيلوا كده لو رسول الله ﷺ كسر الأصنام دي في فترة الدعوة في مكة كان إيه إللي هيحصل\nالدنيا كانت هتقوم عليه وكانوا هيبيدوا المسلمين إبادة كاملة\nلكن دلوقتي بعد ما رسول الله ﷺ بقى هو الحاكم لمكة ومش بس مكة، لأ..ده بقى حاكم لأجزاء كبيرة جداً من الجزيرة العربية بقى هو إللي له الكلمة الأولى والأخيرة،\nفبعد ما صبر رسول الله ﷺ واحد وعشرين سنة على وجود الأصنام خلاص جت لحظة التخلص من المنكر العظيم ده\nطاف رسول الله ﷺ حول الكعبة سبعة أشواط وكسر فيها الأصنام، وكسر بنفسه الصنم الأكبر هُبل،\nوأخرج رسول الله ﷺ سرية بقيادة خالد بن الوليد رضي الله عنه لكسر صنم العُزى،\nوالصنم ده كان من أكبر الآلهة إللي كانت تُعبد من دون الله،\nوأخرج سرية ثانية بقيادة سعد بن زيد الأشْهلي لكسر صنم مَنَاة وهو من أشهر أصنام العرب،\nوأخرج سرِية ثالثة بقيادة عمرو بن العاص لكسر صنم سُواع وهم من الأصنام المشهورة عند العرب،\nواتبقى صنم واحد من الأصنام المشهورة جداً عند العرب وهو صنم اللات، وصنم اللات ده كان موجود في مدينة الطائف عند قبيلة ثقيف،\nفرسول الله ﷺ مش هيقدر يكسر صنم اللات إللي باقي دلوقتي لأن مدينة الطائف مدينة منيعة ولها قصة تانية هنعرفها بعدين إن شاء الله،\nوقصص كسر الأصنام الثلاثة دول هنعرفهم برده بعدين إن شاء الله \nفيبقى دلوقتي أول حاجة رسول الله ﷺ عملها في مكة كانت كسر الأصنام،\nوبعد ما أتم الطواف كان عايز يدخل داخل الكعبة، لكن الكعبة ليها مفتاح ومقفولة،\nالمفتاح كان مع مين بقى\nكان مع بني عبد الدار، فاكرينهم\nإللي كانوا بيحملوا لواء المشركين في غزوة بدر وغزوة أحد \nوهم أعظم القبائل القرشية وإللي كان منهم الصحابي عثمان بن طلحة إللي كان أسلم مع خالد بن الوليد وعمرو بن العاص رضي الله عنهم أجمعين،\nفنادى رسول الله ﷺ لعثمان بن طلحة وطلب منه المفتاح عشان يدخل الكعبة،\nوكان المفتاح مع أمه، فراح لها وطلب منها المفتاح فرفضت إنها تدهوله،\nفقال لها:\n\"لَتُعْطِينِهِ أَوْ لَيَخْرُجَنَّ هَذَا السَّيْفُ مِنْ صُلْبِي\"\nيعني هددها إنها لو مدتهوش المفتاح هيقتل نفسه، فأعطته المفتاح وجاء به لرسول الله ﷺ وفتح لرسول الله ﷺ الكعبة، وكان متعلق داخل الكعبة صور للملائكة وصور لإبراهيم وإسماعيل عليهما السلام وهما يستقْسِمان بالأزلام،\nوالأزلام يعني:\nالأقلامُ أو القِداحُ، وهي عبارة عن أعوادٌ نَحَتوها وكَتَبوا في واحد منها: افْعَل، وفي التاني : لا تَفْعَل، والتالت مكتبوش فيه حاجة سابوه فاضي،\nفكانوا بيخلطوا الأقلام دي ببعض ويسحبوا منها واحد وينفذاو إللي فيه،\nفكانوا بقى راسمين إبراهيم وإسماعيل عليهما السلام وهم بيعملوا كده،\nفرفض رسول الله ﷺ دخول الكعبة إلا لمّا يخرجوا الصور دي، فلما أخرجوها أمر رسول الله ﷺ بطمس الصور دي ومسحها، وقال:\nقاتلهم الله، والله ما استَقْسما بِها قط، جعلوا شيخَنا يستقْسِمُ بالأزلام، ما شأن إبراهيم والأزلام؟\nيعني رسول الله ﷺ بيقولهم إن الصور دي كاذبة وغير صحيحة وملهاش أي علاقة بالواقع وإبراهيم وإسماعيل لم يسْتقْسِما بالأزلام أبدا\nوهنا رسول الله ﷺ بيبين لنا حُرمة تعليقِ التَّصاويرِ أو التَّماثيل في البُيوت أو المساجِد أو غيرِها من الأماكَنِ،\nيعني مينفعش نعلق أي صورة لذوات أرواح سواء كانت حيوان أو إنسان، \nوالبيت إللي فيه صور لا تدخله الملائكة زي ما رسول الله ﷺ قال.\nدخل رسول الله ﷺ للكعبة وكان معه أسامة بن زيد بن حارثة و بلال بن رباح وعثمان بن طلحة،\nوصلى رسول الله ﷺ داخل الكعبة ركعتين وبعدها دَار في نواحي الكعبة وهو يكبر و يوحّد الله،\nوخرج رسول الله ﷺ من الكعبة ودخل بعده على طول عبد الله بن عمر بن الخطاب، وكان عبد الله بن عمر شديد العناية والحرص على الاقتداء برسول الله ﷺ، \nيعني مركز أوي مع أفعال رسول الله ﷺ وبيطبقها كلها بالحرف،\nفلما دخل سأل بلال عن المكان إللي رسول الله ﷺ صلى فيه فشاور له بلال على المكان، فراح صلى في نفس المكان،\nلكن عبد الله بن عمر رضي الله عنه نسي يسأل بلال هو رسول الله ﷺ صلى كم ركعة فصلى\nعبد الله بن عمر كان نموذج عملي لتطبيق سنة رسول الله ﷺ، مكنش بيحب يزود ولا ينقص عنها شيء رضي الله عنه\nبعد ما رسول الله ﷺ خرج من الكعبة أمر بلال إنه يطلع فوق الكعبة ويُؤذن بأذان الإسلام،\nوهنا رسول الله ﷺ عايز يفهّم قريش نقطة مهمة جدا عشان يكونوا فاهمين الإسلام على حقيقته، وهي: \nإن ربنا عز وجل يُعز إللي بينتمى للدين ده بغض النظر عن هو جنسه إيه وبغض النظر عن لونه وعن قبيلته وعن أي شيء،\nفاللي بينتمى للإسلام الانتماء الحقيقي هيبقى عزيز ومَنْ لم ينتمِ إليه فهو ذليل\nتخيلوا الكل ساكت وصوت أذان بلال بس هو المسموع في مكة كلها، \nالله أكبر الله أكبر ...أشهد ألا إله إلا الله...أشهد أن محمدا رسول الله...\nبلال إللي كانوا بيعذبوه أشد العذاب في مكة وكان بيقول أَحَدٌ أَحَد وكان صوته ضعيف ومش بيسمعه غير إللي كان بيعذبه، دلوقتي بيجهر بلا إله إلا الله محمد رسول الله وكل أهل مكة سامعينه مسلمهم وكافرهم،\n\"وَلِلَّهِ الْعِزَّةُ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ \"\nموضوع أذان بلال ده كان شديد جدا على كفار مكة وده أكيد، \nتخيلوا الذل إللي هم فيه بعد ما كانوا هم إللي بيذلوا ويعذبوا بلال، دلوقتي بقى بلال أعز منهم كلهم،\nوشوفوا الحوار إللي حصل بين أبو سفيان بن حرب وعَتّاب بن أُسيد والحارث بن هشام،\nالتلاتة دول كانوا قاعدين في فناء الكعبة وسامعين بلال وهو بيأذن، فقال عتّاب بن أُسيد وكان أحد الشباب في قريش وكان مشرك:\nأكرم الله أسيداً ألاّ يكونَ سمع هذا فسمع منه ما يغيظه، ما وَجدَ محمد غير هذا الغراب الأسود مؤذناً\nيعني بيقول كويس إن أبوه أسيد مات قبل ما ييجي اليوم ده إللي يسمع فيه الأذان من فوق الكعبة،\nهو محمد ﷺ ملقاش غير الغراب الأسود ده يعني بلال هو إللي يؤذن،\nلأن بلال كان من الحبشة فكانت بشرته سوداء فشبهه بالغراب يعني تحقيرا له\nوقال الحارث بن هشام وهو أخو أبو جهل عمرو بن هشام وزعيم من زعماء بني مخزوم:\nأمَا والله لو أعلم أنه مُحِق لاتبعته\nيعني لو أنا كنت متأكد إنه مُحِق وإنه رسول كنت اتبعته، أما أبو سفيان فقال:\nلا أقول شيئاً، لو تكلمتُ لأخبرت عني هذه الحصى\nيعني أنا عارف إنه نبي ولو نطقت بكلمة، الحصى إللي في الأرض ده هيخبره باللي قلته،\nفمر عليهم رسول الله ﷺ وقال لهم :\n\"قد علمتُ الذى قُلتُم\"\nوبدأ يحكي لهم كل واحد قال إيه\nفقال الحارث بن هشام وعَتّاب بن أُسيد:\nنَشْهَد أنك رسول، ما اطّلع على هذا أحدٌ كان معنا فنقول: أخبرك\nيعني بيقولوا إن محدش كان موجود معاهم عشان ينقل الكلام لرسول الله ﷺ وشهدوا إنه فعلا رسول من عند الله ودخلوا في الإسلام\nوكان في بعض شباب من قريش مشركين لما سمعوا أذان بلال قعدوا يستهزؤوا بالاذان ويقلدوه غيظا،\nزي كده لما واحد يقعد يعيب على كلام حد مش طايقه ويقلّده\nفواحد منهم كان عنده ستة عشرة عام 16 قعد يقلد الأذان وكان اسمه أبو مَحذُورَة الجُمَحِي،\nوكان صوته جميل جدا، فسمع رسول الله ﷺ أصوات الشباب دول وأخد باله إن في واحد منهم صوته مختلف، فأمر بهم رسول الله ﷺ فجاءوا له وأمر كل واحد فيهم فيهم إنه يؤذن قصاده،\nوكان أبو محذورة هو آخر واحد أذن فعرف رسول الله ﷺ إن هو ده الصوت إللي سمعه،\nفقال له رسول الله ﷺ إنه يقرب منه، ومسح ﷺ بيده على صدر وناصية أبو محذورة وعلمه الأذان وخلاه هو مؤذن مكة، يقول أبو محذورة بعد ما مسح رسول الله ﷺ على صدره وناصيته : \nفامتلأَ قلبي إيماناً ويقيناً، فعلمت أنه رسول الله\nواستمر الأذان في ذرية أبو محذورة لفترة طويلة جدا من الزمن، يعني هو وذريته كانوا مسؤولين عن الأذان في مكة لسنين طويلة.\nكل أهل مكة مُترقبّين بقى، يا ترى محمد ﷺ إللي آذوه سنين طويلة وعذبوا أصحابه وقتلوا منهم وحاربوه هيعمل فيهم إيه دلوقتي بعد ما بقى هو الحاكم الأول لمكة،\nفكان رد فعل رسول الله ﷺ الفاتح لمكة مختلف تماما عن الملوك إللي كانوا بيدخلوا البلاد بالقوة،\nقال لهم رسول الله ﷺ:\nيا معشر قريش ما تقولون؟\nيعني إيه رأيكم فيّ وتتوقعوا إيه مني،\nقالوا: نقول ابن أخٍ وابنُ عمٍّ رحيم كريم \nيعني انت واحد مننا ومعرفناش عنك غير الرحمة والكرم،\nفأعاد عليهم الكلام كمان مرتين،\nيسألهم ما تقولون وهم يردوا ويقولوا :نقول ابن أخٍ وابنُ عمٍّ رحيم كريم،\nفقال لهم رسول الله ﷺ:\nفَإِنِّي أَقُولُ كَمَا قَالَ أَخِي يُوسُفُ:\n\"لَا تَثْرِيبَ عَلَيْكُمُ الْيَوْم يَغْفِرُ اللَّهُ لَكُمْ وَهُوَ أَرْحَمُ الرَّاحِمِينَ\"\nرسول الله ﷺ عفا عنهم كلهم، مع إنه كان ممكن يأخذهم سبايا ويأخذ أموالهم ومن حقه بعد إللي عملوه معاه ده كله وكمان هو داخل مكة فاتح لها،\nلكن رسول الله ﷺ مش بينتقم لنفسه ولا كان همه أموالهم،\nإللي كان يهم رسول الله ﷺ طول حياته هو نشر الإسلام وإدخال الناس فيه وإنقاذهم من النار،\nوبسبب أخلاقه دي دخل أهل مكة في دين الله أفواجا\n☆طبعا أكيد عايزين تسألوا :\nأمّال فين لما رسول الله ﷺ قال لأهل مكة اذهبوا فأنتم الطّلَقَاء \nشوفوا،\nمفيش ولا حديث له إسناد ثابت جاء فيه لفظ:\n\"اذْهَبُوا فَأَنْتُمْ الطُّلَقَاءُ\"\nيعني كل الأحاديث إللي جاء فيها لفظ: اذْهَبُوا فَأَنْتُمْ الطُّلَقَاءُ\nإما احاديث ضعيفة جدا أو ضعيفة،\nوالصحيح هو الحديث إللي أنا ذكرته فوق\n وإن رسول الله ﷺ قال فيه لأهل مكة زي ما يوسف قال لإخوته لَا تَثْرِيبَ عَلَيْكُمُ الْيَوْم يَغْفِرُ اللَّهُ لَكُمْ وَهُوَ أَرْحَمُ الرَّاحِمِينَ،\nوهتلاقوا في التعليقات رابط فيه تخريج الأحاديث بالضبط وسبب التضعيف\nوممكن تراجعوا كتاب:\n《ما شاع ولم يثبت في السيرة النبوية》\nوكتاب :\n《السيرة النبوية كما جاءت في الأحاديث الصحيحة》\n◇أما بقى كلمة 《الطُّلَقَاءُ》 نفسها لوحدها كده فهي فعلا وردت في السنة في حديث صحيح،\nقَالَ رَسُولُ اللهِ ﷺ:\nالْمُهَاجِرُونَ وَالْأَنْصَارُ أَوْلِيَاءُ بَعْضُهُمْ لِبَعْضٍ،\nوَالطُّلَقَاءُ مِنْ قُرَيْشٍ، وَالْعُتَقَاءُ مِنْ ثَقِيفٍ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ إِلَى يَوْمِ الْقِيَامَةِ\"\nوالطّلقاءُ: همُ إللي عفى عَنْهُمْ رسول الله ﷺ يَوْمَ فَتْح مَكَّةَ ، وأَطْلَقَهُم، فَلَمْ يَسْتَرِقَّهم ويخليهم عبيد عنه\nوَالْعُتَقَاءُ : هنعرف قصتهم إن شاء الله لما نتكلم عنهم\nففرقوا بين حاجتين:\nأهل مكة اسمهم فعلا الطّلقاءُ بنص الحديث إللي قلناه وهو حديث صحيح،\nلكن في نفس الوقت رسول الله ﷺ لم يقل لأهل مكة:\n\" اذْهَبُوا فَأَنْتُمْ الطُّلَقَاءُ\" \nالمهم بقى،\nرسول الله ﷺ لحد دلوقتي لسه معاه مفتاح الكعبة،\nولما رسول الله ﷺ كان طلب المفتاح من عثمان عشان يدخل الكعبة الناس فكّرت إنه هياخد المفتاح منه ويعطيه لحد تاني من بني هاشم مثلا،\nوعثمان نفسه كان متوقع إن رسول الله ﷺ لما ياخد المفتاح منه هيعطي المفتاح لحد غيره غيره بعدين،\nوحتى علي بن أبي طالب طلب من رسول الله ﷺ إنه يخلي المفتاح في بني هاشم، ويبقى كده يجمعوا شرف عظيم جدا ، وهو الجمع بين السقاية والحجابة ومفتاح الكعبة وبكده يزيد شرفهم بين الناس.\n☆طيب ليه بقى أصلا الكل متوقع إن رسول الله ﷺ هياخد مفتاح الكعبة من بني عبد الدار وهيعطيه لحد غيرهم\nموضوع المفتاح ده له قصة حصلت بين رسول الله ﷺ وبين عثمان بن طلحة قبل ما يُسلم عثمان وكان رسول الله ﷺ في مكة قبل ما يهاجر،\nرسول الله ﷺ كان في يوم عايز يدخل الكعبة وطلب من عثمان بن طلحة إنه يعطيه مفتاح الكعبة عشان يدخلها فرفض عثمان بن طلحة وكان ساعتها لسه مشرك،\nوأغلظ عثمان الكلام لرسول الله ﷺ واتكلم معاه بسوء أدب ،فقال له رسول الله ﷺ:\n\"ُيا عثمان لعلك ترى هذا المفتاح يوماً بيدي أَضَعُهُ حيث شئتُ\"\nيعني هييجي اليوم إللي المفتاح ده هيكون في إيدي وساعتها سأعطيه للشخص إللي أنا عايزه\nفقال له عثمان:\n\"لقد هلكت قريش يومئذٍ وذَلّت\" \nيعني مستحيل يحصل حاجة زي كده إلا بقى لو قريش هلكت ساعتها وأصابها الذل،\nفقال له رسول الله ﷺ:\n\" بل عَمَرت وعَزّت يَومِئذ\"\nيعني رسول الله ﷺ يقصد إنها هتكون ساعتها عامرة وعزيزة بالإسلام،\nوعدت السنين وأسلم عثمان وتحقق كلام رسول الله ﷺ وبقى المفتاح في إيده ويقدر يُعطيه لأي حد هو عايزه ومحدش هيقدر يعترض،\nوعثمان بن طلحة مش ناسي الموقف ولكنه دلوقتي خلاص بقى من جنود المسلمين الطائعين لأمر رسول الله ﷺ،\nلكن رسول الله ﷺ رجّع المفتاح لعثمان بن طلحة وقال له:\n\"هاك مفتاحَك يا عثمان، اليومَ يومُ برٍّ ووفاء، اليوم يومُ برٍّ ووفاء، خذوها خالدةً تالدةً لا ينزَعُها منكم إلا ظالم\"\nولحد زماننا دلوقتي مفتاح الكعبة مع نسل بني عبد الدار زي ما قال رسول الله ﷺ\nمين بقى إللي شايف الأحداث دي كلها\nالأنصار\nشايفين عفو ورأفة رسول الله ﷺ بأهل مكة، وخلاص بقى مكة بقت مسلمة ورسول الله ﷺ مكنش أصلا عايز يخرج منها وخرج منها وهو مضطر،\nفدلوقتي الوضع الظاهر لهم إن رسول الله ﷺ بين أهله وعشيرته وفرحان بإسلامهم والوضع استقر خلاص،\nحتى إنهم قالوا لبعض:\n\"أما الرّجل فأَدركَتْه رغبةً في قريتِه ورأفةً بعشيرتِه\"\n☆بصراحة كان موقف صعب ومؤلم بالنسبة للأنصار، لو تصورتم موقفهم وإللي عملوه خلال السنين إللي فاتت دي كلها وفي اللحظة دي حسوا إنهم اتنسوا ومبقاش لهم لازمة،\nهتحسوا فعلا بالألم إللي كان جواهم في الوقت ده\nلكن هل فعلا خلاص كده دورهم انتهى ومبقاش لهم لازمة زي ما همّ كانوا متخيلين؟\nولّا وضعهم هيبقى إيه بالضبط بعد فتح مكة؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 193, "l": "الجزء 167 | احداث السنه الثامنه من الهجرة | تحطيم الاصنام الكبري  بعد الفتح", "u": "https://www.facebook.com/groups/710210019782034/permalink/836543687148666/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعة_وستون\n#أحداث_السنة_الثامنة_من_الهجرة\n#تحطيم_الأصنام_الكبرى_بعد_الفتح\nوقفنا المرة إللي فاتت عند الأنصار لما قالوا عن رسول الله ﷺ:\n\"أما الرّجل فأَدركَتْه رغبةً في قريتِه ورأفةً بعشيرتِه\"\nهم قالوا كده لما شافوا عفو رسول الله ﷺ عن أهل مكة، فكانوا مفكرين إن خلاص كده دورهم انتهى وإن رسول الله ﷺ هيسيبهم ويرجع لمكة، ولو تفتكروا في بيعة العقبة الثانية الأنصار قالوا لرسول الله ﷺ:\n\" إنّ بيننا وبين القومِ حبالاً وإننا قاطعُوها\"\nيعني احنا عندنا عهود ومواثيق بينا وبين اليهود وبين القبائل، واحنا هنقطع عهودنا معاهم وهنقاتل الأحمر والأسود من الناس، فهل لو ربنا نصرك هترجع لقومك وتسيبنا؟\nفرسول الله ﷺ ساعتها كان قالهم لأ وإنه هيفضل معاهم،\nلكن هم دلوقتي شايفين رقة ورحمة رسول الله ﷺ في تعامله مع قومه، \nفخافوا إن رسول الله ﷺ يرجع لمكة بعد ما أسلم أهل مكة وبقوا خلاص جزء من الدولة الإسلامية،\nفهم من حبهم لرسول الله ﷺ مش عايزينه يبعد عنهم نهائي، \nالأنصار كانوا قالوا الكلام ده لما كان رسول الله ﷺ واقف على جبل الصفا بينظر على مكة وبيدعو الله ويحمده وكانوا هم واقفين تحت جبل الصفا، \nيعني رسول الله ﷺ واقف على قمة الجبل وهم واقفين تحت.\n☆طيب عارفين صحيح ليه رسول الله ﷺ كان واقف بينظر على مكة من على جبل الصفا بالذات وبيحمد ربنا\nلو تفتكروا،\nرسول الله ﷺ وقف نفس الموقف ده من واحد وعشرين سنة وقعد ينادي على أهل مكة كلهم ويقول لهم إنه رسول من عند الله ووقف بينذرهم إن في حاجة اسمها آخرة وفيها نعيم وفيها عذاب أليم للي مش هيؤمن بيه،\nوكان رد فعل أهل مكة إنهم كذبوه وآذُوه وعمه نفسه قال له تبا لك ألهذا جمعتنا،\nوإللي كان يشوف موقف رسول الله ﷺ ساعتها مكنش يتخيل أبدا إن هييجي يوم ورسول الله ﷺ هيقف في نفس المكان وهو منتصر وأهل مكة داخلين في الإسلام،\nفوقف رسول الله ﷺ على نفس المكان إللي كانوا كذبوه فيه، لكن المرة دي وقف فيه بعد ما صدقوه وكأن شريط طويل من الذكريات بيمر أمام أعين رسول الله ﷺ في اللحظة دي وبيحمد ربنا على الفتح المبين ده\nفي اللحظة دي بقى بعد ما قال الأنصار كلمتهم، جاء الوحي لرسول الله ﷺ وأخبره بكلام الأنصار، فنادى رسول الله ﷺ على الأنصار وقال لهم: انتم قلتم:\n\" أَمَّا الرَّجُلُ فقَدْ أَخَذَتْهُ رَأْفَةٌ بعَشِيرَتِهِ، وَرَغْبَةٌ في قَرْيَتِهِ\"؟\nفرد عليه الأنصار وقالوا:\n\" قد قُلْنا ذاك يا رسولَ اللهِ\"\nيعني احنا فعلا قلنا الكلام ده، فقال لهم رسولُ اللهِ ﷺ :\nأَلَا فَما اسْمِي إذًا؟\nقالها ثلاث مرات، لأنهم قالوا 《أما الرجل》 فرسول الله ﷺ بيعاتبهم إنهم قالوا كلمة الرجل، وكمل كلامه وقال لهم:\n\"كلَّا! إنِّي عبدُ اللهِ ورسولُه هاجَرْتُ إلى اللهِ وإليكم، المَحْيا محياكم والمَماتُ مماتُكم\"\nيعني أنا عبد الله ورسوله متقولوش عليّ رجل، وأنا هاجرت لله وإلى دياركم عشان أعيش فيها فمش هسيبها ومش هرجع عن هجرتي لله وهفضل معاكم ومش هعيش غير عندكم ومش هموت غير عندكم، \nومش معنى إني تعاطفت مع الأحداث إللي حصلت في مكة وفرحت بإسلام أهلي وعشيرتي إني هقعد في مكة وأترككم، ومستحيل أخلِف عهدي معاكم\nفأقبَلوا يبكون ويقولون:\nواللهِ ما قُلْنا الَّذي قُلْنا إلَّا ضنًّا باللهِ ورسولِه\nيعني بدأوا يبكوا ويبينوا لرسول الله ﷺ همّ ليه قالوا الكلمة دي،\nوحلفوا بالله إنهم مقلوش الكلام ده إلا بُخلًا بما آتاهم اللهُ مِن كرامةٍ، يعني مش عايزين حد تاني ياخد الكرامة إللي ربنا أعطاها لهم من نصرة الإسلام ونصرة رسول الله ﷺ،\nوشُحًّا بِرسولِ اللهِ ﷺ أنْ ينتقلَ مِن بَلدتِنا إلى بلدتِه،\nيعني مش عايزين رسول الله ﷺ يسيب المدينة ويرجع بلده إللي هي مكة،\nفقال لهم رسول الله ﷺ:\nوإنَّ اللهَ ورسولَه يُصدِّقانِكم ويعذِرانِكم \nيعني ربنا ورسوله مصدقين كلامهم إللي قالوه وبيعذروهم،\nوقال رسول الله ﷺ عن الأنصار:\n\"آية المنافق بُغْض الأنصار ، وآية المؤمن حُب الأنصار\"\nيعني علامة إن الشخص ده منافق إنه يكره الأنصار؛ لأن الأنصار ساعدوا رسول الله ﷺ ونصروا الدين ومكنش لهم أي جزاء في الدنيا في مقابل تضحيتهم بالمال والنفس \nفاللي بيكره الأنصار يبقى منافق لأن المنافقين بيكرهوا رسول الله ﷺ وبيكرهوا يشوفوا الإسلام منتصر،\nوإللي بيحب الأنصار بيكون مؤمن وده دليل قاطع على كمال إيمانه كمان؛ لأنه بيكون أحبهم في الله يعني أحبهم لأنهم نصروا رسول الله ﷺ وأيدوه وآوُوه، وفي الحديث:\n\"مَن أحب في الله وأبغض في الله فقد استكمل الإيمان\"\nوكل إللي البذْل إللي بذله الأنصار قبل الفتح له قيمة عالية جدا في الإسلام بعكس مَن بذل ماله ونفسه بعد الفتح؛\nلأن البذل والتضحية والجهاد قبل فتح مكة كان في وقت الشدة ووقت العناء ووقت المشقة، \nومش ممكن أبداً يتساوى من أَنفق قبل الفتح وقاتل مع إللي إللي أسلم وأنفق في سبيل الله بعد الفتح،\nوربنا نفسه هو إللي قال كده:\n\"لا يَسْتَوِي مِنْكُمْ مَنْ أَنْفَقَ مِنْ قَبْلِ الْفَتْحِ وَقَاتَلَ أُوْلَئِكَ أَعْظَمُ دَرَجَةً مِنَ الَّذِينَ أَنْفَقُوا مِنْ بَعْدُ وَقَاتَلُوا وَكُلًّا وَعَدَ اللَّهُ الْحُسْنَى وَاللَّهُ بِمَا تَعْمَلُونَ خَبِيرٌ\"\nأيوة الاتنين هيدخلوا الجنة ولهم الأجر والثواب، لكن فرق كبير جدا بين درجاتهم في الجنة،\nوحتى حصل موقف بيوضح المعنى ده،\nجاء واحد من الصحابة اسمه مُجَاشِع بن مسعود رضي الله عنه بأخيه مُجَالِد بن مسعود عشان يُعلن إسلامه أمام رسول الله ﷺ بعد الفتح،\nومجَاشِع كان من إللي أسلموا قبل الفتح ومُجالد أخوه من إللي أسلموا بعد الفتح، \nفجاء بأخيه قال لرسول الله ﷺ : جئتُك بأخي لتبايعه على الهجرة،\nفقال له رسول الله ﷺ : \nذهب أهل الهجرة بما فيها\nيعني خلاص مبقاش في هجرة وأصحاب الهجرة سبقوا الناس بها،\nفقال مجاشع: على أي شيء تُبَايِعه؟\nيعني طيب هتبايعه عليه بقى دلوقتي، فقال له رسول الله ﷺ:\nأبَايعه على الإسلام والإيمان والجهاد.\nفزمن الهجرة إلى رسول الله ﷺ في المدينة خلاص انتهى بعد فتح مكة\n☆ كل الكلام ده يعلمنا إن الإنسان إللي بيعمل الصالحات في وقت الشدة ووقت الأزمات ووقت ما تكون الناس كلها ضده ويبقى ثابت على الصالحات دي مهما تعرض للأذى؛ مختلف عن إللي بيعمل الصالحات في وقت الرخاء وانتشار المُعِينين على الطاعة،\nحتى رسول الله ﷺ قال إن هييجي زمن القابض فيه على دينه زي القابض على الجمر،\nيعني الدين إللي المؤمن متمسك بيه ده هيكون سبب في الأذى والألم إللي بيتعرض له زي إللي بيكون قابض على جمرة نار في إيده شوفوا بيحس بألم شديد أد إيه\nفأجر المسلم في زمن الغُربة لما يكون متمسك بالدين وإللي حواليه مُفرطين، مختلف تماما عن أجر المسلم إللي كان عايش مثلا في خلافة إسلامية ومفيش حد بيحارب الدين زي ماحنا شايفين دلوقتي\nكده خلاص الأنصار اطمنوا إن رسول الله ﷺ مش هيسيبهم وهيفضل معاهم،\nحصلت بقى في مكة أحداث متفرقة، خلونا نشوف أهم الأحداث دي:\nقلنا المرة إللي فاتت إن رسول الله ﷺ أرسل خالد بن الوليد وعمرو بن العاص وسعد بن زيد الأشهلي في ثلاث سرايا عشان يهدموا ثلاثة أصنام مشهورة عند العرب.\n☆ملحوظة:\nأنا المرة إللي فاتت كنت قلت لكم إن إللي خرج لهدم الصنم مناة هو سعيد بن زيد بن عمرو بن نُفيل،\nوده غير صحيح ، الصحيح إن إللي خرج لهدم صنم مناة هو سعد بن زيد الأشهلي معلش اتخلبطت بين الاتنين، وأنا خلاص صلحته في الجزء إللي فات، فكان لازم أنبه المرة دي على الخطأ ده عشان إللي كان قرأه قبل التعديل\nخلونا بقى ناخدهم واحد واحد ونشوف حصل إيه:\n◇أولا:\nسرية خالد بن الوليد إللي كان معاه فيها ثلاثين فارس لهدم صنم العُزّى:\nالعزى ده صنم معناه : الصنم الأَعز، وهو أنثى، وكان بعض العرب يعتقد إن الأصنام بنات الله فيعبدونها، حاشاه سبحانه،\nوالعُزَّى أكبر أصنام قريش وبني كنانة وكانوا بيطوفوا حوله زي ما كانوا بيطوفوا حول الكعبة،\nوكان العرب بيسموا بعض أبناءهم باسم 《عبد العُزَّى》 زي أبو لهب عم رسول الله ﷺ إللي كان اسمه عبد العزى،\nوربنا أنزل فيه قرآن قال:\n\"أفَرَأَيْتُمُ اللَّاتَ وَالْعُزَّى ۩ وَمَنَاةَ الثَّالِثَةَ الْأُخْرى\"\nولو تفتكروا في غزوة أُحد أبو سفيان رفع العُزَّى كشعار في غزوة أحد وقال لرسول الله ﷺ والصحابة:\n\"لنا العُزَّى ولا عزى لكم\"\nفأمر رسول الله ﷺ  بالرد عليه فقالوا: \n\"الله مولانا ولا مولى لكم\"\nفالصنم ده كان صنم عظيم جدا عند العرب، فأمر رسول الله ﷺ خالد إنه يروح إلى منطقة نخلة شرقا هيلاقي هناك صنم العزى، فلما يوصل هناك يهدمه،\nوفي آراء كتيرة بقى عن شكل الصنم ده كان عامل إزاي،\nوالراجح إن العزى كانت عبارة عن بيت بقرية نخلة على ثلاث شجرات مقدسة عندهم، \nيعني بيت وفي داخل الفناء بتاعه ثلاث شجرات، وداخل البيت كان في شيطانة، وكان البيت ده له سَدَنة يعني خدم  مسؤولين عنه،\nفكان المشركون بيعبدوا البيت ده ويطوفوا به زي الكعبة كده، والشيطانة دي كانت تكلمهم من الداخل، فتزيدهم ضلال على ضلالهم،\nلما وصل خالد لموقع الصنم لقى الثلاث شجرات فقطعها، وهدم البيت إللي كان مبني عليها، وفكر إنه كده خلاص هدم  العُزَّى،\nورجع خالد رضي الله عنه لرسول الله ﷺ وأخبره باللي عمله،  فسأله رسول الله ﷺ: ما رأيت؟\nيعني شوفت إيه، فأخبره خالد باللي شافه، \nفرد عليه رسول الله ﷺ وقال : \n\"ارجع فإنك لم تصنع شيئا\"\nفرجع خالد بن الوليد لمكان الصنم فرآه السّدَنة فراحوا داخلين في وسط الجبل وتعمقوا فيه وهم بينادوا :\nيا عُزَّى...يا عُزَّى!\nفجاءها خالد فلقى امرأة عريانة ناشرة شعرها عمّالة تاخد التراب من الأرض وتحط على رأسها وبتدعو بالويل\nفضربها خالد بالسيف لحد ما قتلها،\nورجع خالد لرسول الله ﷺ وأخبره باللي حصل فقال له رسول الله ﷺ:\n\" تِلْكَ الْعُزَّى\"\nيعني هي دي بقى العزى إللي الناس كانوا بيعبدوها\n☆ملحوظة عشان محدش يتوه في النص\nالشياطين ممكن يتجسدوا في صورة بشر عادي، وهنشوف قصة حصلت فعلا مع أبو هريرة بعدين إن شاء الله عن الموضوع ده،\nوممكن يتجسدوا في صورة حيوانات زي الأفعى وزي الكلب الأسود،\nولو تم قتل الصورة إللي الشيطان متجسد فيها دي، الشيطان بيموت عادي،\nيعني الشيطان لو مثلا متجسد في شكل أفعى، واحنا قتلنا الأفعى دي يبقى قتلنا الشيطان المتشكل على هيئة الأفعى ده،\nفلما خالد قتل المرأة دي فهو قتل الشيطانة إللي كانت متجسدة في شكل المرأة، واضح كده\nطبعا في أدلة كتير وأمثلة كتير على كلامي ومعظم الأمثلة في أحاديث صحيحة،\nهتلاقوا رابط في التعليقات من موقع الدُّرر السَّنِيّة بيتكلم عن تشكل الجن في هيئة بشر و حيوانات وكله بالأحاديث وكمان هتلاقوا تخريج الأحاديث دي وبيان الصحيح من الضعيف منها\n◇الصنم الثاني إللي رسول الله ﷺ أمر بهدمه كان :\nصنم مَناة وأخرج له سرية بقيادة سعد بن زيد الأشهلي، من قبيلة بني عبد الأشهل من الأنصار وكان معاه عشرين فارس،\nصنم مناة ده كان من الأصنام المشهورة عند العرب هو كمان، وكان إللي بيعبدوه في الجاهلية هم الأوس والخزرج وكانوا أكثر العرب تعظيما له، عشان كده رسول الله ﷺ أخرج سعد بن زيد الأشهلي بالذات لأنه من الأوس،\nيعني رسول الله ﷺ كان عايز الأصنام تتكسر على يد الناس إللي عبدوها في يوم من الأيام،\nصنم مناة كان موجود في منطقة المُشَلّل وهو جبل يُهبط منه إلى قديد من ناحية البحر الأحمر،\nفراح سعد بن زيد لمكان الصنم ولما وصل قابله سَادِن الصنم، يعني الخادم بتاعه فقال له السَّادن:\nما تريد؟ يعني عايز إيه، فقال له سعد:\nهدم مناة، يعني أنا عايز أهدم الصنم مناة، فقال له السَّادن:\nأنت وذاك، يعني اعمل إللي تعمله،\nفمشي سعد باتجاه الصنم فخرجت له امرأة عريانة سوداء ثائرة الرأس، شعرها منكوش يعني وبتدعو بالويل، وتضرب صدرها،\nفقال السادن: مناة! دُونك بعض عُصَاتُك.\nيعني واحد من إللي بيعصوا أوامرك جاي لك، فتقدم سعد وقتلها وتقدم أصحابه وهدموا الصنم إللي كان موجود ورجعوا لرسول الله ﷺ وأخبروه باللي حصل\n☆ملحوظة:\nقصة المرأة إللي قتلها سعد بن زيد دي قبل هدم صنم مناة بيذكرها أهل التاريخ في كتبهم، لكن ملهاش سند صحيح زي قصة خالد لما قتل المرأة الشيطانة،\nيعني هي قصة《ضعيفة》لكن أنا قلتها لكم عشان لو سمعتوها من حد تبقوا عارفين إنها ضعيفة، لكن أهل التاريخ بيذكروها، وهي مش مبني عليها أي أحكام شرعية عشان كده بيحكوها عادي، \nلكن الثابت الصحيح إن سعد بن زيد وأصحابه في السرية حطموا الصنم مَنَاة\n◇السرية الثالثة إللي أخرجها رسول الله ﷺ لهدم الصنم الثالث للعرب سُوَاع خرجت بقيادة عمرو بن العاص رضي الله عنه،\nوالصنم ده كان منصوب في أرض اسمها رُهاط من أرض يَنبع، والقرية دي تبعد عن مكة بحوالي خمسة كيلو، وكان إللي بيعبد الصنم ده قبيلة هُذَيل ومُزينة وبعض القبائل الأخرى،\nولما جاء عمرو رضي الله عنه للصنم عشان يهدمه جاء خادم الصنم عشان يحاول يمنعه من هدمه وبيقوله إن الصنم مش هيسمح له إنه يهدمه،\nفقال له عمرو: \"حتى الآن أنت في الباطل، ويْحك! هل يسمع أو يبصر؟!\" \nيعني عمرو بيقوله هو انت لسه عايش في الباطل، هو انت شايفه بيسمع ولّا بيشوف\nوتقدم عمرو وهدَم الصنم وهدموا بيت خزانته، لأن كان حول كل صنم بيت مبني زي الكعبة كده وكانوا بيعظموه وبيطوفوا حوله ،\nوهنا السادن لما شاف الصنم اتكسر وحتى مدافعش عن نفسه قال: أسلمت لله \nورجع عمرو ومعاه السرية لمكة وأخبر رسول الله ﷺ.\n☆ملحوظة:\nيُقال إن صنم سُواع ده إللي هدمه عمرو هو نفس الصنم بتاع قوم نوح إللي كانوا بيعبدوه، وربنا كان ذكره في القرآن:\n\"وَقَالُوا لاَ تَذَرُنَّ آلِهَتَكُمْ وَلاَ تَذَرُنَّ وَدًّا وَلاَ 《سُوَاعًا》 وَلاَ يَغُوثَ وَيَعُوقَ وَنَسْرًا\"\nواحنا اتكلمنا بالتفصيل في قصص الانبياء عن الآلهة دي،\nوكان الصنم سُواع ده اندفن في التراب بعد الطوفان،\nوإللي حفر وأخرجه من التراب هو عمرو بن لُحي الرجل إللي بدّل دين العرب وأدخل الأصنام لشبه الجزيرة العربية، وكنا اتكلمنا عنه في بداية السيرة،\nعرف بقى مكانه إزاي الله أعلم، وهل المعلومة دي صحيحة ولّا لأ؟ الله أعلم\nهي المعلومة جذبت انتباهي فقلت أقولها لكم\nالمهم بقى،\nفين سهيل بن عمرو وصفوان بن أمية\nهنعرف المرة الجاية إن شاء الله إيه إللي حصل معاهم"}, {"n": 194, "l": "الجزء 168 | احداث السنه الثامنه من الهجرة | موقف رسول الله مع سهيل وصفوان", "u": "https://www.facebook.com/groups/710210019782034/permalink/836543830481985/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانية_وستون\n#أحداث_السنة_الثامنة_من_الهجرة\n#موقف_رسول_الله_مع_سُهيل_وصفوان\nوقفنا المرة إللي فاتت عند سؤالنا عن سُهيل بن عمرو وصفوان بن أمية حصل معاهم إيه،\nاحنا كنا قلنا إنهم جمعوا أوباش قريش وكوّنوا فرقة لقتال المسلمين وانهزموا وهربوا كلهم بعد كده وكان معاهم عكرمة بن أبي جهل وعرفنا قصته وإنه دخل في الإسلام خلاص،\nاتبقى سهيل بن عمرو وصفوان بن أمية.\n◇أولا: سهيل بن عمرو:\nبعد ما سهيل بن عمرو هرب، دخل بيته وقفل عليه بابه لأن إللي كان بيدخل بيته ويقفل عليه بابه كان بيبقى آمن زي ما قلنا قبل كده،\nلكن سهيل مش هيفضل محبوس في بيته على طول،\nو برده كان خايف يخرج ؛\nلأنه خايف إنه يُقتل واحنا عارفين تاريخ سهيل بن عمرو مع رسول الله ﷺ عامل إزاي وموقفه الشديد على رسول الله ﷺ يوم صلح الحديبية وإللي عمله مع أبو جندل ابنه\nحتى سهيل نفسه كان بيقول:\n\"تذكرتُ أثَرِي عند محمد وأصحابه، فليس أحدٌ أسوأْ أثراً مني، وإني لَقِيتُ رسول الله ﷺ يوم الحديبية بما لم يَلْقه أحد\"\nيعني بيقول إنه افتكر الحاجات إللي عملها مع رسول الله ﷺ و الصحابة فلقى إن محدش ساب عندهم أثر سيء زيه.\nفأرسل سهيل إلى ابنه عبد الله إنه يشفع له عند رسول الله ﷺ عشان يُعطيه الجِوَار،\nوعبد الله بن سهيل ده كان أسلم من زمان وكان من الصحابة إللي حضروا غزوة بدر، وكان موجود في جيش رسول الله ﷺ يوم فتح مكة،\nفذهب عبد الله بن سهيل إلى رسول الله ﷺ فقال له:\nيا رسول الله! هل تُأَمِّنْ أبي؟\nيعني هل تعطي أبي سهيل الأمان إنه لو خرج من بيته محدش يقتله،\nفقال له رسول الله ﷺ:\n\"نعم، هو آمن بأمان الله، فليظهر\"\n☆شوفتوا تعامل رسول الله ﷺ مع زعماء مكة عامل إزاي\nرسول الله ﷺ لو كان عايز الانتقام وهمّه بس \n《احتلال مكة》 زي ما في ناس بتتهم رسول الله ﷺ بكده مكنش إداله الأمان وكان أمر جيش المسلمين إنه يتتبعه لحد ما يقتله،\nوده فعلا إللي الدول المحتلة بتعمله لما تدخل تحتل دولة تانية، تلاقيهم بيتتبعوا الأمراء والوزراء والكبراء في البلد في كل مكان عشان يقتلوهم أو يسجنوهم في السجن فترات طويلة، أو يُمثّلوا بهم أو...أو...\nلكن رسول الله ﷺ أعطى له الأمان وكمان قال له 《 فليظهر》\nيعني خليه يخرج من بيته عادي ويتحرك زي ما هو عايز ميخافش، \nوقال رسول الله ﷺ للصحابة:\nمن لَقِي سهيل بن عمرو فلا يَشُد النظر إليه، فليخرج، فلعمري إن سهيلاً له عقل وشرف،\nوما مثل سهيل جَهِل الإسلام، ولقد رأى ما كان يُوضع فيه أنه لم يَكن له بناء\"\nيعني إللي يشوف فيكم سهيل بن عمرو ميقعدش يبصله أوي ويخوّفه، ومحدش يقول له كلمة تضايقه أو يعلق عليه بأي بتعليق سلبي، \nهو خلاص عرف مشكلته وعرف إن إللي كان بيعمله عشان يحارب الإسلام مكنش له أي فايدة وهو رجل حكيم شريف، فمش واحد زيه هيجهل الإسلام \nراح عبد الله بن سهيل لأبيه وأخبره باللي قاله رسول الله ﷺ، فقال سهيل:\n\"كان والله براً صغيراً وكبيراً\"\nيعني بيقول إن رسول الله ﷺ طول عمره مُحسن سواء لما كان صغير أو حتى لما كِبر،\nوخرج سهيل من بيته وكان بيتحرك عادي جدا في مكة وحضر غزوة حنين مع رسول الله ﷺ وهو مُشرك وأعطاه رسول الله ﷺ من الغنائم وأسلم بعد غزوة حنين في مكان اسمه الجُعْرانة قريب من مكة، وهنعرف التفاصيل إن شاء الله لما ييجي وقتها\nوكان سُهيل بعد إسلامه كثير الصيام والصلاة وكان بيخرج للجهاد كتير جدا مع إنه كان كبير جدا في السن رضي الله عنه.\n◇نشوف بقى صفوان بن أمية:\n أمية بن خلف أبو صفوان كان من أشد المعاندين لرسول الله ﷺ، وكان أمية هو إللي بيعذب بلال رضي الله عنه لو تفتكروا، وكان أمية بن خلف من إللي قُتلوا في بدر،\nصفوان بن أمية ورث الكراهية للإسلام والمسلمين من أبيه،\nوحارب رسول الله ﷺ بكل طاقته،\nوكان من الناس إللي الْتَفّت على المسلمين في غزوة أحد من عند جبل الرماة هو وخالد بن الوليد رضي الله عنه، \nواشترك اشتراك كبير في قتل سبعين من شهداء الصحابة رضي الله عنهم وأرضاهم، \nواشترك كمان في غزوة الأحزاب، وطبعا مننساش تدبيره لمحاولة قتل رسول الله ﷺ مع عمير بن وَهْب وكنا اتكلمنا عنها في الجزء الثالث والستين،\nوساعتها  تعهّد صفوان بن أمية لعمير بن وهب إنه يتحمل عنه عياله وإنه يسدد عنه دينه، في مقابل إن عمير بن وهب يروح يقتل رسول الله ﷺ ،\nوشوفنا إزاي عمير أسلم ساعتها، \nوآخر محاولة بقى لصفوان ضد رسول الله ﷺ و المسلمين  لما جمع أوباش مكة عشان يقاتل المسلمين لما دخلوا مكة، يعني هو له تاريخ أسود مع المسلمين\nفهرب صفوان بن أمية من مكة كلها، وفي رواية بتقول إن صفوان كان من الناس إللي رسول الله ﷺ أهدر دمهم وأمر بقتلهم،\nفدلوقتي مفيش له أي مكان في مكة وحتى خارج مكة معظم القبائل إما على الإسلام أو في بينها وبين رسول الله ﷺ معاهدات، يعني من الآخر كده محدش هيستقبله في الجزيرة العربية،\nفقرر إنه يركب البحر ويشوف بقى هيروح فين،\nفخرج فعلا في اتجاه البحر الأحمر ومش معاه غير غلام اسمه يَسَار، لحد ما وصل إلى البحر الأحمر،\nوبعدين شاف كده من بعيد إن في رجل بيتتبعه فخاف، وقال لغلامه: \nويْحَك انظر مَن ترى\nيعني شوف لنا مين إللي جاي ورانا ده،\nفقال له الغلام: هذا عُمَيْر بن وهب\nوكان عمير بن وهب صديق حميم لصفوان بن أمية قبل ما يسلم عُمَير،\nفقال صفوان : ما أصنع بعمير\nوالله ما جاء إلا يُريد قتلي، فهو الآن مسلم قد ظاهر محمداً عليّ\nيعني عمير صاحبي خانني وبقى من أتباع محمد ﷺ، ودلوقتي أكيد هو جاي ورايا عشان عايز يقتلني.\n☆وهو إيه إللي جاب عمير بن وهب هنا أصلا\nعمير بن وهب كان راح لرسول الله ﷺ وقال له:\nيا نبي الله! إن صفوان بن أمية سيد قومه،\nوقد خرج هارباً منك ليقذف نفسه في البحر، فأمِّنْه يا رسول الله.\nفقال له رسول الله ﷺ: هو آمن\nفقال عمُير: يا رسول الله! فأعطني آية يعرف بها أمانك.\nيعني عمير بيطلب الأمان لصفوان من رسول الله ﷺ، وبيطلب منه إنه يديله حاجة كده لما يوريهاله يبقى متأكد فعلا إن رسول الله ﷺ إداه الأمان وإن عمير مش بيخدعه،\nفأعطاه رسول الله ﷺ عمامته إللي كان لابسها لما دخل مكة،\nوقيل أعطاه الرداء بتاعه،\nوخرج عمير يتتبع صفوان لحد ما لحقه ووصل عنده، فقال له صفوان:\nياعمير ما كفاك ما صنعت بي؟!\nحمّلتني دَيْنك وعيالك، ثم جئت تريد قتلي\nيعني مش كفاية إللي انت عملته فيّ، خلتني أسدد عنك دينك وأرعى عيالك في مقابل إنك تروح تقتل محمد وفي الآخر منفذتش الاتفاق إللي بيننا وكمان جاي دلوقتي عايز تقتلني،\nفقال عمير :\nفداك أبي وأمي! الله الله في نفسك أن تهلكها،\nهذا أمان من رسول الله ﷺ وقد جئْتُك به\nيعني انت كده هتهلك نفسك لو ركبت البحر وتركت بلدك ، ارجع معايا، رسول الله ﷺ أعطاك الأمان،\nفقال له صفوان: وَيلك! اغرُب عني فلا تكلمني\nيعني ابعد عني متكلمنيش،\nفقال له عُمَير: فداك أبي وأمي!\nجئتك من عند أفضل الناس، وأبر الناس وأحلم الناس وخير الناس! ابن عمك، عزّهُ عزُّك، وشَرَفُه شَرَفُك، ومُلْكُه مُلْكُك\nيعني بيوصف له أد إيه رسول الله ﷺ مُحسن وحليم وإنه أفضل الناس، وبيرغبه في العز والشرف وإن رسول الله ﷺ مش هيذله ولا ياخد منه شرفه،\nفقال صفوان:\nأنا خايف منه على نفسي\nفقال له عمير وهو بيطمنه:\nهو أحلم من ذلك وأكرم\nفرجع صفوان مع عمير بن وهب، وراحوا لرسول الله ﷺ  فقال صفوان:\nإنّ هذا يزعم أنك أمَّنتني\nيعني بيقول لرسول الله ﷺ إن عمير بيقول إنك أعطتني الأمان، فهل فعلا كلامه صحيح،\nفقال له رسول الله ﷺ :صَدَق\nفقال له صفوان :\nفاجعلني في الخِيَارِ شهرين.\nيعني إديني مهلة شهرين أفكر في الإسلام وأشوف هعمل إيه، فقال له رسول الله ﷺ:\nأنت في الخيارِ أربعة أشهر\nيعني خد أربع شهور مش شهرين بس فكر في الإسلام براحتك ولك الأمان،\nلكن صفوان أسلم قبل ما تنتهي الأربع أشهر بكتير، أسلم بعد غزوة حنين، وهنعرف وقتها أسلم إزاي،\nلكن الفترة إللي كانت قبل إسلامه كان عايش في مكة عادي جدا وسط المسلمين ومحدش بيتعرض له بأذى،\nوبأسلوب العفو بتاع رسول الله ﷺ ده كسب قلوب كل الناس إللي اتعاملت معاه\nمن أهم الأحداث إللي حصلت في مكة بعد الفتح هو إن امرأة من بني مخزوم سرقت، وكانت أسلمت يوم الفتح،\nالمرأة المَخْزُومِيَّةٌ دي كانت تَسْتَعِيرُ الْمَتَاعَ وَتَجْحَدُهُ،\nيعني تستلف الحاجة من الناس وتقول لهم بعد كده أنا مخدتش منكم حاجة\nوكانت مشهورة بين الناس بكده، وفوق كده كمان سرقت\nوحد السرقة في الإسلام هو قطع اليد، يعني المرأة دي لازم تُقطع يدها ما دام ثبت عليها السرقة فعلا،\nلكن المشكلة إن دي امرأة من بني مخزوم وهي شريفة من الأشراف،\nوقبيلة بني مخزوم قبيلة كبيرة جداً،\nو زي ما احنا عارفين إن العلاقة بين بني مخزوم إللي كان زعيمها أبو جهل، وبين بني هاشم إللي منها رسول الله ﷺ كانت علاقة حساسة جداً، \nوكان التنافس بينهم على كل حاجة تقريباً، يعني الموقف كان موقف حرج جدا مع القبيلة دي بالذات\n☆ليه موقف حرج\nاحنا شايفين رسول الله ﷺ عمال يتأَلّف القبائل ويعفو عن ده ويعطي الأمان لده،\nيعني هو أَلّف قلوب بني أمية إللي زعيمهم أبو سفيان،\nو أَلّف قلوب بني عبد الدار لما ترك معاهم مفتاح الكعبة،\nوأَلّف قلوب غيرها من القبائل،\nلكن الموقف دلوقتي مع بني مخزوم هيتفهم غلط من ناس لسه داخلين حديثا في الإسلام ولسه أثار العصبية القبلية متغلغلة في قلوبهم،\nهيتفهم إن بني هاشم كده بيعلّموا على بني مخزوم، وكده رسول الله ﷺ يبقى مستقصدهم ومش بيتألف قلوبهم زي باقي القبائل،\nوبالتالي بالوضع ده في احتمال كبير إنهم ينقلبوا على المسلمين انقلاب مش عارفين العواقب بتاعته هتكون إيه\nفيا ترى بقى رسول الله ﷺ هيحل المشكلة دي إزاي\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 195, "l": "الجزء 169 | احداث السنه الثامنه من الهجرة | حد السرقه في الإسلام", "u": "https://www.facebook.com/groups/710210019782034/permalink/836544000481968/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وتسعة_وستون\n#أحداث_السنة_الثامنة_من_الهجرة\n#حد_السرقة_في_الإسلام\nاتكلمنا المرة إللي فاتت عن المرأة المخزومية إللي كانت بتستلف حاجة الناس وبعدين تقولهم أنا مخدتش منكم حاجة،\nوأضافت للجحود ده بقى إنها سرقت، وحد السرقة في الإسلام للي يثبت عليه السرقة فعلا هو قطع اليد،\nربنا بيقول:\n\"وَالسَّارِقُ وَالسَّارِقَةُ فَاقْطَعُوا أَيْدِيَهُمَا جَزَاءً بِمَا كَسَبَا نَكَالًا مِّنَ اللَّهِ ۗ وَاللَّهُ عَزِيزٌ حَكِيمٌ \"\nطيب خلّونا الأول كده نفهم موضوع السرقة في الإسلام،\nالسرقة هي: إن واحد بالغ مُكلّف ياخد مال واحد تاني في الخفاء ،\nيعني مينفعش نقيم حد السرقة على المجنون مثلا إللي ملوش عقل يميز بيه\nفعشان تُقطع يد السارق ده لازم شروط معينة تتحقق،\nيعني عشان فعلا نقدر نسمي إللي حصل ده سرقة وبالتالي تُقطع يد السارق، لازم يكون عندنا ستة شروط يتحققوا \n《مع بعض》عشان يتم قطع يد السارق:\n◇الشرط الأول:\nأن يكون أَخذُ الشيء على وجه الخِفْيَةِ ومن غير ما يكون له فيه شبهة حق، فإن لم يكن على وجه الخِفْيَةِ فلا تُقْطَع، \nيعني مثلا واحد يدخل مكان وهو متخفّي عشان يسرق إللي فيه من غير ما حد يشوفه،\nلكن لو واحد بيسرق على مَرأى ومسمع من الناس في الشارع مثلا زي واحد سرق شنطة وهرب قصاد الناس، ده لا تُقطع يده لأن صاحب المال يمكنه طلب النَّجدة من إللي حواليه ومفيش هنا استخفاء\nلكن طبعا له عقوبة تانية، لكن مش قطع اليد.\nوميكونش له شبهة حق، يعني ممكن واحد بيسترجع ماله إللي اتاخد منه بالغصب أو له حق عند الشخص إللي بياخد  منه المال ده بأي طريقة يعني. \n◇ الشرط الثاني:\nأن يكون المسروق مالا محترماً؛ لأن ما ليس بمال لا حرمة له، كآلات اللهو والخمر والخنزير.\nيعني الحاجة إللي اتسرقت دي تكون لها قيمة...مال حلال له حُرمة زي مثلا المال المعروف وزي الذهب، مش تكون حاجة مُحرمة زي آلات الموسيقى والخمر ولحم الخنزير مثلا.\n◇الشرط الثالث:\nأن يكون المسروق نِصاباً ، وهو ثلاثة دراهم إسلامية أو ربع دينار إسلامي ، أو ما يُقابل أحدهما من النقود الأخرى.\nيعني لازم الحاجة إللي اتسرقت دي تكون بلغت نصاب السرقة، ونصاب السرقة هو ربع دينار فأكثر،\nوالدينار الواحد يساوي أربعة جرامات ذهب وربع،\nيبقى حد السرقة هو ثمن جرام ذهب بالإضافة إلى ربع الربع الباقي،\nيعني مثلا لو هنفترض إن جرام الذهب بمائة جنيه، يبقى الدينار يساوي أربعمائة جنيه وخمسة وعشرين جنيه،\nيبقى حد السرقة هنا هيبقى ربع ال 425 يعني هيبقى : \n106,25 يعني مائة وستة جنيه وخمسة وعشرين قرش،\nطبعا ده مثال للتوضيح بس\nلكن لازم نشوف سعر الذهب كام في الحقيقة عشان نقدر نطلع نِصاب السرقة بالضبط وهل فعلا الحاجة إللي اتسرقت دي بلغت النصاب ولاّ لأ\n◇رابعا:\nأن يُأخُذَ المسروق من حِرْزه ، وحرز المال : ما تَعَوَّدَ الناس على حِفظ أموالهم فيه كالخِزَانَة مثلاً .\nيعني يا جماعة الحاجة إللي اتسرقت دي تكون محطوطة في مكان لحفظ الأموال، زي المحفظة أو الخزنة أو أي مكان لحفظ الأموال،\nيعني مش واحد سايب فلوسه كده قصاد الناس ممكن أي حد ياخدها، هنا مش هتبقى سرقة لأن الأموال مش موجودة في مكان لحفظ المال.\n◇الشرط الخامس:\nلا بد من ثُبُوتِ السرقة، وتكون إما : بشهادة عَدْلَيْنِ ، أو بإقرار السارق على نفسه مرتين.\nيعني لازم نتحقق من وقوع السرقة فعلا، وده بيكون إما بيكون عن طريق وجود شاهدين عَدل يشهدوا على وقوع السرقة، \nأو إن السارق نفسه يعترف على نفسه مرتين إنه فعلا سرق.\n◇الشرط السادس:\nلابد أن يُطالِب المسروق منه بماله فإذا لم يطالِب لم يجب القطع، \nيعني لازم الشخص إللي اتسرق منه يطالب بالحاجة إللى اتسرقت منه دي وإلا خلاص كده مفيش سرقة أصلا\nفاحنا كده لازم يكون عندنا الشروط الستة دي عشان نقدر نطبق حد السرقة، ولو شرط واحد بس مش متوفر يبقى مش هينفع نطبق حد السرقة وهو قطع اليد،\nوعلى فكرة قطع اليد يعني قطع اليد اليمنى فقط من عند الرّسغ\n إللي عند مفصل الكف كده مش اليد كلها،\nولو حصل تاني وسرق تُقطع رجله اليسرى.\nفالمرأة المخزومية توفر فيها الشروط الستة إللي قلنا عليها دي عشان كده استحقت قطع اليد،\nلكن المشكلة إللي كانت بتواجه رسول الله ﷺ زي ما قلنا المرة إللي فاتت إنه لو طبّق حد السرقة على المرأة الشريفة دي من بني مخزوم احتمال كبير تحصل مشاكل مع قبيلة بني مخزوم،\nلكن برغم كل المشاكل إللي ممكن تحصل قرر رسول الله ﷺ إنه يطبق حد السرقة على المرأة المخزومية\n☆طب ليه رسول الله ﷺ اختار إنه يطبق الحد وأهل مكة لسه يادوب داخلين في الإسلام وميعرفوش أحكام الإسلام،\nومن وجهة النظر العامة إن المفروض إن رسول الله ﷺ يورّي أهل مكة سماحة الإسلام عشان مينفروش من الإسلام ويكرهوا الدين يعني زي ما في ناس بتقول كده فعلا في زماننا دلوقتي\nإللي يجاوبنا على السؤال ده هو رسول الله ﷺ نفسه،\nشوفوا حصل إيه\nانتشر الخبر بين أهل مكة إن رسول الله ﷺ هيقطع يد المرأة المخزومية،\nفذهب بنو مخزوم لرسول الله ﷺ عشان يستشفعوا للمرأة ويطلبوا من رسول الله ﷺ إنه يعفو عنها،\nلكن مقدروش يكلموه مباشرة فراحوا لأسامة بين زيد بن حارثة،\nوأسامة يعتبر حفيد رسول الله ﷺ لأن أبوه زيد كان اسمه زيد بن محمد فترة طويلة قبل تحريم التبني،\nوكان رسول الله ﷺ بيحب زيد جدا وبيحب ابنه أسامة جدا،\nحتى إن أسامة كان يُسمى بين الصحابة ب:\nالحِبّ بن الحِب، وشوفنا إزاي إن رسول الله ﷺ لما دخل مكة كان مركّب أسامة وراه على الناقة بتاعته، فكان أسامة له مكانة خاصة عند رسول الله ﷺ،\nفجاء بنو مخزوم لأسامة وطلبوا منه إنه يشفع لهم عند رسول الله ﷺ ويقول لرسول الله ﷺ إنه يعفو عن المرأة المخزومية،\nفأسامة أخد الموضوع بسهولة ويُسر ودخل على رسول الله ﷺ وبدأ يكلمه ويطلب منه إنه يعفو عن المرأة المخزومية أو إنه ياخد من بني مخزوم فداء بدل ما المرأة تُقطع يدها،\nلكن رد فعل رسول الله ﷺ كان شديد، غضب رسول الله ﷺ جدا وتغيّر وجهه وقال لأسامة:\n\" أَتَشْفَعُ فِي حَدٍّ مِنْ حُدُودِ اللَّهِ؟!\"\nيعني انت عايزني أعطّل حد من حدود ربنا عشان خاطر مكانة المرأة وقبيلتها؟\nوهي ده الإجابة على السؤال إللي سألناه\nرسول الله ﷺ قرر إنه يقيم حد السرقة على المرأة المخزومية مُضحيًا باللي ممكن يحصل من أحداث ممكن تكون دامية وبيعرفنا وبيفهمنا معنى مهم جدا وهو:\nإنه لا يمكن أبداً لأي إنسان مهما كان نسبه ومهما كان شريفاً ومهما كان عظيماً إنه يتغاضى عن حد من حدود الله أو يعطلها، أو يقوم بأمر من الأمور يمنع من إقامتها في الدولة الإسلامية، حتى لو كانت العواقب شديدة\nفهنا أسامة قال لرسول الله ﷺ:\n\"اسْتَغْفِرْ لي يا رَسولَ اللَّهِ\" فاستغفر له رسول الله ﷺ،\nفرسول الله ﷺ لم يقبل شفاعة أسامة ولا شفاعة أي حد من الصحابة؛ لأن الحدود دي مُلْك لربنا هو إللي قال عليها إنها تتنفذ، مش رسول الله ﷺ هو إللي حاططها من عنده\nولما جاء وقت العشاء قام رسول الله ﷺ بين الناس وخطب خطبة يوعظهم فيها ووضح لهم فيها إن العدل فعلا هو أساس المُلك وإن الكلمة مش مجرد شعار وخلاص،\nوقال لهم:\n\"إِنَّمَا أَهْلَكَ الَّذِينَ قَبْلَكُمْ ، أَنَّهُمْ كَانُوا إِذَا سَرَقَ فِيهِمُ الشَّرِيفُ تَرَكُوهُ ، وَإِذَا سَرَقَ فِيهِمُ الضَّعِيفُ أَقَامُوا عَلَيْهِ الحَدَّ ، وَايْمُ اللَّهِ لَوْ أَنَّ فَاطِمَةَ بِنْتَ مُحَمَّدٍ سَرَقَتْ لَقَطَعْتُ يَدَهَا\"\nيعني بيقول لهم إن من أسباب هلاك الناس قبلكم هو الظلم؛ لأنهم كانوا مش بيعاقبوا الشريف أو الرئيس أو حد له مكانة عالية لما بيغلط ومش بيقيموا عليه الحد،\nأما بقى لو واحد ضعيف وَضِيع ملوش شرف ولا له حد يسند عليه ولا أَتْباع؛ أقاموا عليه الحد\nورسول الله ﷺ بيوريهم مثال عملي وبيقول لهم إن لو فاطمة بنت محمد سرقت لقطعتُ يدها،\nيعني فاطمة هي أشرف الناس نسبا لأنها بنت رسول الله ﷺ خير البشر ومع ذلك لو أنها سرقت مش هيمنعها شرفها ونسبها أو حتى حبي لها من إني أقيم عليها الحد\n☆عارفين،\nاحنا بنقع في الخطأ ده من غير ما ناخد بالنا بس في مواقف تانية\nمقصدش حد السرقة وكده، لأ ..أنا بتكلم على مواقف في حياتنا اليومية، إلا مَن رحم الله طبعا،\nهقول لكم مثال،\nمثلا طفل في مدرسة أخطأ خطأ شديد، فعشان الولد ده ابن فلان الفلاني، أو من العيلة الفلانية تلاقي إدارة المدرسة أو حتى مدرسة الفصل تتغاضى عن الخطأ ده ومتكبرش الموضوع وحتى متعاقبش الولد،\nلكن تعالوا شوفوا نفس الخطأ حصل من ولد تاني ملوش واسطة ولا من عيلة معروفة ولا له سند، إدارة المدرسة ممكن تعمل فيه إيه وتبهدله إزاي، \nوالواقع مليان أمثلة على كلامي،\nفهنا الموقف بالضبط زي ما رسول الله ﷺ قال:\n\" إِذَا سَرَقَ فِيهِمُ الشَّرِيفُ تَرَكُوهُ ، وَإِذَا سَرَقَ فِيهِمُ الضَّعِيفُ أَقَامُوا عَلَيْهِ الحَدَّ\"\nفوجه الشبه هنا مش السرقة، لكن العقاب الواقع على الضعيف عشان هو ضعيف ورفع العقاب عن الشريف عشان هو شريف،\nوقيسوا بقى على كده مواقف تانية كتييير، فلازم ناخد بالنا عشان منهلكش زي ما رسول الله ﷺ حذّر\nعارفين بقى المرأة المخزومية إللي قُطعت يدها دي، تابت بعد كده وحسُنت توبتها، وتزوجت وكانت بتيجي للسيدة عائشة لما تكون محتاجة حاجة والسيدة عائشة بتوصل حاجتها لرسول الله ﷺ، سبحان الله\n☆فاحنا نستفيد من قصة المرأة المخزومية دي إن مينفعش الشفاعة في الحدود إذا بلغت الحاكم أو القاضي،\nلكن لو حصل تسوية بين السارق وبين الشخص إللي اتسرق منه وحصل عفو قبل ما يوصلوا للحاكم أو القاضي خلاص يبقى مفيش مشكلة ومش محتاج إنه تُقطع يده،\nلكن لو السارق اتمسك واتسلّم للحاكم أو القاضي خلاص يجب على الحاكم تنفيذ حد ربنا إللي أمر بيه\nوفعلا حصلت قصة مع صفوان بن أمية شبيهة بكده بعد ما أسلم،\nكان صفوان مرة نايم في المسجد على ثوب بتاعه، وكان ثمنه ثلاثين درهم، فجاء رجل واختلس الثوب بتاع صفوان، يعني سحبه من تحت صفوان من غير ما صفوان يحس،\nفالرجل ده اتمسك وجاءوا به لرسول الله ﷺ، فأمر رسول الله ﷺ أن تُقطع يد الرجل، فقال صفوان:\nأَنَقْطَعُهُ مِنْ أَجْلِ ثَلاَثِينَ دِرْهَمًا\n أَنَا أَبِيعُهُ ، وَأُنْسِئُهُ ثَمَنَهَا \nيعني احنا نقطع إيده عشان ثلاثين درهم؟!خلاص أنا هبعها له، ويبقى يجيب لي تمنها بعدين مش مشكلة، فقال له رسول الله ﷺ:\n\"فَهَلاَّ كَانَ هَذَا قَبْلَ أَنْ تَأْتِيَنِي بِهِ\"\nيعني مش كنت تعمل كده قبل ما تجيلي بيه؛ لأن كده خلاص الحكم فيها بقى حق للشرع مش للشخص صاحب الواقعة\n☆عندنا طبعا سؤالين مهمين هنا\n◇السؤال الأول:\nممكن ناس تقول طيب والرجل إللي اتقطعت إيده ده هيعمل إيه بعد كده، وهيشتغل إزاي، ده كده هيروح يتسول وأعداد المتسولين هيزيدوا،\nولو كان عنده أولاد وأسرة كده أسرته هتتشرد\nشوفوا يا جماعة،\nمن أصول الإيمان وأركانه وقواعده عندنا احنا المسلمين هي إن المؤمن يمتثل أمر ربنا، ويعتقد كده إن أمر ربنا ده هو الحق، وإن كل إللي يخالف أمر ربنا فهو باطل\nفربنا أمرنا بإقامة الحدود إللي شرعها لنا،\nفاحنا بنقيم الحدود دي طاعة لله تعالى واحنا مؤمنين إنها أصلح وأنفع ما تكون،\nواحنا ممكن نعرف إيه هو وجه الصلاح إللي في حد معين وممكن منعرفش، وده مش هيغير من إيماننا بحكمة ربنا شيء\nوخصوصا إن ربنا هو إللي خلقنا وعارف إيه الأصلح لينا،\n\"أَلَا يَعْلَمُ مَنْ خَلَقَ وَهُوَ اللَّطِيفُ الْخَبِيرُ\"\nحلو الكلام لحد كده\nندخل بقى في تفصيل حكمة ربنا من قطع يد السارق \nاحنا بسؤالنا إللي سألناه ده بيخلينا بننظر للسارق المجرم الجاني نظرة رحيمة، وللأسف النظرة دي فيها جهل وعدم حكمة، ليييه\nلأننا نظرنا للجاني بعين الرحمة، لكن في نفس الوقت لم ننظر إلى المجتمع إللي ياما اتكوى بنار المجرم ده\nهو مش من حق الناس إنها تعيش في أمان وهم مطمنين على حياتهم وتجارتهم وأهلهم وأبناءهم،\nويمارسوا أعمالهم وحياتهم من غير خوف من سارق أو قاطع طريق \nيعني يا جماعة تخيلوا كده معايا إن في رجل فقير عنده ابن مريض محتاج عملية مهمة، وبقاله فترة عمال يحوش في الفلوس واستلف كمان عشان يكمل فلوس العملية وكتب على نفسه شيكات،\nوبعدين جاء سارق وسرق فلوسه دي،\nالأب ساعتها هيعمل إيه بالله عليكم ؟\nطيب إيه ذنب ابنه هنا إللي ممكن يتحرم من الحياة بسبب جشع السارق ده؟\nولّا إيه ذنب أبوه إنه يشوف ابنه بيموت قصاده ومش قادر يعمل له حاجة؟\n☆الواحد دمه فار والله من مجرد تخيل الموقف، فما بالكم باللي فعلا عاش ظروف زي كده وأسوأ من كده\nوأمثلة تانية كتير على فكرة بتحصل حوالينا،\nفاشمعنى بقى ننظر للسارق الظالم المعتدي بعين الرحمة ولا ننظر للمجني عليه بعين الرحمة؟\nهل ده كده عدل وإنصاف يعني؟\nمع إنه أصلا ممكن مش هيبقى متسول ولا حاجة وممكن يشتغل شغل يتناسب مع حالته، مش هيبقى عاجز يعني،\nوحتى لو افترضنا إنه بقى عاجز ، مش هو إللي عمل كده في نفسه\nأيوة إللي حصل ده ممكن يكون مفسدة له، ولكنها مفسدة مُحتملة مغتفرة في سبيل تحقيق مصلحة أكبر وأعظم ، وهي مصلحة أمن واستقرار المجتمع كله\nوبالرغم بقى كل ده فشريعة الإسلام بقى جمعت بين الرحمة للطرفين، يعني ربنا شرع حد السرقة عشان يمنع الجريمة من أصلها،\nوبكده محدش هيتجرأ على ارتكاب جريمة السرقة، بالعكس هيبقى خايف من العقوبة،\nويبقى خلاص المجتمع اترحم من ظلم السارق المعتدي ده\nوفي نفس الوقت نظر للسارق المجرم ده هو كمان بعين الرحمة، تخيلوا\nطب إزاي بقى الكلام ده \n◇أولا:\nربنا شرع عقوبة تردعه عن السرقة من قبل حتى ما يعملها،\nيعني لو هو عارف يقينا إن إيده هتتقطع لو سرق مش هيفكر أصلا في السرقة،\nهو مين إللي يستغنى عن إيده مقابل شوية فلوس\n◇ثانيا:\nإنه فتح باب التوبة للسارق بعد ما يسرق وبالتالي إسقاط العقوبة عن نفسه لو تاب عن جرائمه قبل القبض عليه،\n\" فَمَنْ تَابَ مِنْ بَعْدِ ظُلْمِهِ وَأَصْلَحَ فَإِنَّ اللَّهَ يَتُوبُ عَلَيْهِ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ\"\nوطبعا مننساش إن من شروط التوبة إرجاع الحقوق لأصحابها،\nيعني لو واحد سرق يجب عليه إنه يرجع إللي سرقه ده لصاحبه\n◇ثالثا:\nالحد لا يُقام على السارق إلا بالشروط إللي احنا قلناها، ولو شرط واحد بس مش متوفر لا تُقطع يده،\nوعلى فكرة الشروط دي ممكن يكون صعب تحقيقها على الأرض الواقع أصلا،\nفالموضوع مش انتقام ووحشية زي ما في ناس بتقول\nده ربنا بيُعطي فرص كتيرة للسارق ده عشان يتوب ويرجع الحق لأصحابه من غير ما تُقطع يده.\n◇رابعا:\nالإسلام خلّى كل شُبهة أو احتمال في ثبوت الجريمة يتفسر لمصلحة الجاني، فلا يُقام عليه الحد مع الشبهة والاحتمال،\nيعني لو ظهر إن في احتمال لو بسيط إن السارق ده لم يسرق لا يُقام عليه الحد،\nلأن القاعدة في الشرع بتقول: 《إن الحدود تُدرَأ بالشبهات》\nيعني لو احنا عندنا شبهة بسيطة إن السارق ده لم يسرق، يُدفع عنه تطبيق الحد\nفلو تعدى الجاني كل الحواجز إللي قلناها دي، وهَتك حرمة الشرع ، واعتدى على حرمات الناس وحقوقهم لحد ما ثبتت عليه جريمته ، واستوجب الحد،\nفده معناه إنه وصل في الإجرام لدرجة عالية أوي ولازم يُقام عليه حد السرقة عشان يتوقف عند حده ويُمنع من تكرار جريمته، ويُنقذ المجتمع من عدوانه.\n◇خامسا:\nمع إللي قلناه ده فلسه رحمة ربنا مستمرة، فهو جعل الحد ده كفارة للسارق وتطهيرا له من جريمته، ولما يقابل ربنا يوم القيامة يقابله وهو طاهر من الكبيرة دي\nلأن رسول الله ﷺ قال:\n\" فمن أصاب من ذلك شيئا فعوقب به في الدنيا فهو كفارة له\"\nيعني خلاص كده مش هيتحاسب عنه يوم القيامة؛ لأن العقوبة أو الحد بتاع الدنيا بيمسح الذنب خلاص\n◇سادسا:\nوبعد كل ده ربنا أمر بالإحسان للسارق ده بعد إقامة الحد عليه وعدم تعنيفه أو تعييره أو شتمه، وكمان أمر بقبوله في المجتمع أخ لنا عادي جدا زي ما كان قبل ما يسرق،\nوده إللي حصل مع المرأة المخزومية، قُطعت يدها وتابت وحسنت توبتها وكمان تزوجت وكملت حياتها عادي جدا.\n◇سابعا:\nالإسلام رحم السارق ده بوجود حد السرقة بإنه نجّاه من انتقام المجني عليه أو أسرته؛\nلأن المجني عليه قلبه بيتقطع طلبا للانتقام والتشفّي من إللي استولى على ماله ده،\nفلما يشوف إن السارق أُقيم عليه الحد وأخذ جزاءه العادل قلبه بيهدأ وبالتالي مش هيفكر في الانتقام وندخل بقى في غابة وكل واحد ياخد حقه بإيده\nيعني باختصار يا جماعة الحد الشرعي رحمة من الله الرحمن الرحيم لعباده وبعباده،\nولو الحدود إللي ربنا أمر بيها لم تُطبق، هينتشر الفساد العريض في الأرض، والواقع أكبر دليل على كلامنا ده،\nفي عهد رسول الله ﷺ والصحابة والتابعين والأجيال إللي كانت بعدهم وكانوا بيطبقوا شرع ربنا 《كامل》 مكنش الفساد منتشر زي ما هو منتشر دلوقتي،\nفبعد إللي قلناه ده كله، أي النظامين أعدل وأحسن ؟\nالنظام إللي بينظر نظرة شاملة للجاني والمجني عليه ويراعي حقوق كل طرف\nولّا النظام القاصر إللي بيغلّب أحد الأمرين على الآخر \n◇السؤال التاني المهم هو:\nاحنا قلنا إن مينفعش أي حد مهما كان يعطل حدود ربنا،\nطيب نرد بإيه على الناس إللي بتقول إن عمر بن الخطاب رضي الله عنه عطّل حد السرقة في عام الرّمَادة\nطبعا الكلام ده غير صحيح تماما عن عمر بن الخطاب رضي الله عنه \nعمر لم يُعطل حد السرقة، ومفيش أي أثر صحيح عن عمر بن الخطاب رضي الله عنه إنه عطل حد السرقة عام الرمادة\nوعام الرمادة ده حصلت فيه مجاعة والناس مبقتش لاقية الأكل،\nواحنا قلنا إن في شروط لازم تجتمع عشان يُطبق حد السرقة وفصلنا الكلام فيها، \nوقلنا إن من الشروط دي بلوغ نصاب السرقة، وإن ميكونش في شبهة حق في المال المسروق،\nفالسرقة في الوقت ده مَكنش في حاجة بالغة للنصاب أساسا، فإزاي بقى إللي بياخد حاجة عشان ياكلها يبقى كده سارق\nفاللي كان بياخد حاجة كان بياخدها عشان ياكلها وإلا هيموت من الجوع، \nوإللي بيسرق في زمن المجاعة له شبهة حق في المال ده؛ لأن المضطر إلى الطعام يجب على المسلمين إطعامه\nلكن لو حصل فعلا واجتمعت الشروط كلها في إثبات السرقة كان عمر هيقيم الحد؛ لأن مفيش حد يقدر يعطل حد من حدود الله مهما كان\nطبعا الكلام إللي قلته ده كلام مختصر لكلام كتير\nإللي عايز التفصيل هيلاقي الروابط في التعليقات من موقع الإسلام سؤال وجواب\nحصلت بقى أحداث تانية في مكة بعد الفتح، من الأحداث دي....\nهنعرف الجزء الجاي إن شاء الله"}, {"n": 196, "l": "الجزء 170 | احداث السنه الثامنه من الهجرة | هند بنت عتبه وتسامح رسول الله معها", "u": "https://www.facebook.com/groups/710210019782034/permalink/836544340481934/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعون\n#أحداث_السنة_الثامنة_من_الهجرة\n#هند_بنت_عتبة_وتسامح_رسول_الله_معها\nاتكلمنا المرة إللي فاتت عن بعض الأحداث إللي حصلت في مكة وكان من الأحداث دي سرقة المرأة المخزومية واتكلمنا عن حد السرقة،\nقبل ما نكمل باقي الأحداث عندنا سؤالين من التعليقات،\n◇السؤال الأول:\nإيه هو حكم الناس إللي بتسرق الأطفال أو بتخطفهم من أهلهم\nالعلماء قالوا إن إللي يعمل كده يدخل في الحِرابة، ويُقام عليه حد الحِرابة، زي ما ربنا بيقول:\n\" إِنَّمَا جَزَاءُ الَّذِينَ يُحَارِبُونَ اللَّهَ وَرَسُولَهُ وَيَسْعَوْنَ فِي الأَرْضِ فَسَادًا أَنْ يُقَتَّلُوا أَوْ يُصَلَّبُوا أَوْ تُقَطَّعَ أَيْدِيهِمْ وَأَرْجُلُهُمْ مِنْ خِلافٍ أَوْ يُنفَوْا مِنَ الأَرْضِ ذَلِكَ لَهُمْ خِزْيٌ فِي الدُّنيَا وَلَهُمْ فِي الآخِرَةِ عَذَابٌ عَظِيمٌ\"\nوحد الحرابة هو : \nالقتل أو الصّلب يعني يتعلّق على خشبة ثم يُقتل وهو مصلوب بحَرْبَة،\nأو تقطيع الأيدي والأرجل من خلاف: يعني قطع اليد اليمنى مع القدم اليسرى، أو النفي من الأرض،\nإللي يحدد أنهي عقوبة يستحقها إللي أفسد في الأرض ده هو الحاكم أو القاضي، بيشوف أحداث القضية كانت إيه،\nهل خطف بس، أو خطف وتعذيب، أو خطف وتعذيب وتعدي أو....أو....\nفي حالات تستحق القتل وفي حالات تستحق  الصلب وحالات تستحق القطع و هكذا\n◇طبعا يا جماعة موضوع الحِرابة ده باب واسع وفي اختلافات بين العلماء في تطبيقه وشروطه، فصعب إني أشرحها كلها ومش قضيتنا أصلا\nإللي يهمنا بس هنا إننا نعرف إن الناس إللي بتخطف الأطفال دي لهم حكم في الشرع، وحكم رادع كمان، ولو الحكم ده اتطبق مش هنلاقي حد بيخطف أطفال تاني، بس مين يعقل\n☆السؤال التاني:\nما هو جزاء السارق الذي لم تتوفر فيه كل شروط السرقة\nمادام لم تتوفر فيه كل شروط السرقة يبقى لا يُطبق عليه حد السرقة وهو قطع اليد،\nلكن لو كان الشيء المسروق أقل من نصاب السرقة فهنا السارق يُعزّر،\nو التعزير معناه :التأديب على ذنوب لم تُشرع فيها الحدود،\nيعني القاضي أو الحاكم يحكم بعقوبة معينة على الشخص إللي عمل حاجة غلط والحاجة دي ملهاش حد في الشرع،\nزي إللي سرق مبلغ معين ولكنه أقل من نصاب السرقة،\nفلو الموضوع وصل للقاضي أو الحاكم فهو يقضي بعقوبة هو يحددها ويشوفها مناسبة عشان يأدب السارق ده \nولو موصلش للقاضي فباب المسامحة والتوبة مفتوح،\nلكن العقوبة أو الحد الشرعي يتطبق لو وصل للحاكم أو القاضي زي ما قلنا المرة إللي فاتت\n《لو عايزين تفصيل للكلام إللي قلته كله \nهتلاقوه في روابط في التعليقات\n》\nنرجع بقى لباقي الأحداث إللي حصلت في مكة، \nرسول الله ﷺ قعد يبايع الناس إللي أسلموا جديد، \nفجاء أبو بكر الصديق رضي الله عنه بأبيه أبو قحافة عشان يُسلم،\nوأبو قحافة قبل فتح مكة على طول لما كان رسول الله ﷺ موجود بذي طُوى وكان الخبر انتشر إن جيش المسلمين هيدخل مكة، كان قال لأصغر بناته إنها تاخده وتطلع بيه على الجبل وكان ساعتها أعمى،\nفلما طلعوا على الجبل سألها: شايفة إيه؟\nفقالت له: سوادا مُجتَمِعاً، فقال لها : تلك والله الخيل!\nوكملت البنت كلامها وقالت:\nوأرى بين ذلك السواد رجلا يسعى مقبلا ومدبراً.\nيعني شايفة رجل رايح جاي بين الخيول دي،\nفقال لها أبو قحافة: ذاكَ الوازِع، يعني إللي بيأمر الخيل ويحركها،\nوكان ساعتها رسول الله ﷺ أمر أبو بكر يكون هو المشرف على الخيل،\nفالرجل إللي البنت شافته كان رايح جاي ده هو أبو بكر الصديق أخوها وابن أبي قحافة،\nفكملت البنت كلامها وقالت لأبوها:\nوأرى ذلك السواد قد انتشر، يعني الخيول بدأت تتحرك من مكانها، فقال لها أبوها:\nقد والله دُفعت الخيل، فاسرعي\nيعني الخيل هتدخل مكة خلاص فخلينا نرجع بيتنا بسرعة قبل ما يمسكونا، \nفنزلوا من على الجبل لكن ملحقوش يوصلوا بيتهم، وأخذتهم خيل المسلمين،\nفجاء به أبو بكر ودخل على رسول الله ﷺ وكان أبو قحافة رجل كبير جدا في السن وشعره شاب،\nفلما شافه رسول الله ﷺ قال لأبي بكر :\nهلّا تركت الشيخ في بيته حتى أكون أنا آتيه فيه ؟ \nيعني كنت خلي الشيخ في بيته بلاش تتعبه وأنا كنت هجيله وأبايعه على الإسلام،\nفقال أبو بكر :\n\"يا رسول الله هو أحقّ أن يمشي إليك من أن تمشي أنت إليه\"\nيعني يا رسول الله انت إللي تستاهل إن هو إللي يجيلك مش انت إللي تروحله\nفأجلسه أبو بكر أمام رسول الله ﷺ، فمسح رسول الله ﷺ صدر أبي قحافة وقال له:\n أسلم! فأسلم أبو قحافة، وقال رسول الله ﷺ: غَيِّرُوا هَذَا بشيء ، وَاجْتَنِبُوا السَّوَادَ.\nيعني أمرهم إنهم يصبغوا شعر أبي قحافة بلون تاني لكن الأسود لأ،\nوطبعا أمر تغيير الشيب هنا على الاستحباب، يعني مستحب إن إللي يشيب شعره ويتحول للأبيض إنه يصبغه بلون تاني ما عدا الأسود لأن الصبغ بالأسود مُحرم،\nفصبغ الشعر الأبيض سنة أمر بها رسول الله ﷺ مادام كانت بغير الأسود\nجاءت مجموعة من النساء عشان يُبَايِعن رسول الله ﷺ على الإسلام،\nوكان رسول الله ﷺ بيبايع الرجال باليد، يعني يحط إيده في إيدهم ويبايعهم على الإسلام والجهاد،\nأما النساء فكان يبايعهن مُشافهة، يعني بالفم بس من غير ما يضع إيده في إيدهم،\nكان من النساء إللي جاءت للبيعة هند بن عتبة زوجة أبي سفيان، \nوهند كانت من الناس إللي رسول الله ﷺ أهدر دمها،\nوهند بنت عتبة لها تاريخ طويل من العداء مع المسلمين، وخصوصا مع رسول الله ﷺ ، \nفمفيش في تاريخ المسلمين امرأة هي أشد عداء لرسول الله ﷺ من هند بنت عتبة\nهي موقفها صعب وقلبها كان مليان كُره وعداء للمسلمين من قبل غزوة بدر، \nومن بعد غزوة بدر بقى زاد الحقد والكُره في قلبها؛ لأن أبوها وأخوها وعمها وابنها قُتلوا في غزوة بدر\nوشوفنا إنها خرجت مع جيش المشركين في غزوة أُحد، وهي إللي مثّلت بجسد حمزة وقطعت أنفه وشقت بطنه لو تفتكروا، لكنها لم تأكل كبده زي ما شرحنا في الجزء الخامس والسبعين،\nواستمرت على كرهها وحربها للإسلام لحد آخر لحظة قبل فتح مكة ورفضت كلام أبي سفيان لما جاء وقال لأهل مكة يستسلموا ويدخلوا بيوتهم وكانت عايزاهم يقاوموا ويقاتلوا رسول الله ﷺ وجيشه،\nلكن سبحان الله، جاءت لرسول الله ﷺ عشان تبايعه على الإسلام، وجاءت وهي منتقبة مع باقي النساء ومحدش عارف إنها هند،\nفقال رسول الله ﷺ للنساء إللي كان من ضمنهم هند:\n\"بَايِعْنَنِي عَلَى أَلاَّ تُشْرِكْنَ بِاللهِ شَيْئًا\"\nفقالت هند:\nوالله إنك لتأخذ علينا ما لا تأخذه من الرجال\nيعني في تفصيلات كتيرة للنساء، الرجال بايعوا بيعة واحدة وخلاص من غير التفصيل ده،\nفرسول الله ﷺ مردش عليها، هي كانت منتقبة وميعرفش مين إللي بتتكلم دي، فكمّل رسول الله ﷺ كلامه وقال: \n\"وَلاَ تَسْرِقْنَ\"\nفوقفت هند وقالت:\n\"يا رسول الله! إنَّ أبا سفيان رجل شحيح لا يعطيني ما يكفيني، ويكفي بَنِيّ، فهل عليَّ من حرجٍ إذا أخذت من ماله بغير علمه؟\nيعني أبو سفيان بخيل، فهي بتاخد من ماله بغير علمه عشان تصرف على نفسها وعلى عيالها،\nفقال لها رسول الله ﷺ:\n\"خُذِي أَنْتِ وَبَنُوكِ مَا يَكْفِيكِ بِالْمَعْرُوفِ\"\nيعني خدي من ماله إللي يكفيكِ انتِ وعيالك بالمعروف، يعني المال إللي هتاخده ده تكون محتاجاه في حاجات أساسية ناقصاها مش رفاهيات وكماليات\n☆وطبعا يا جماعة دي مش غيبة ولا حاجة لأنها بتستفتي رسول الله ﷺ، فلازم توصف له الحالة كلها عشان يقدر يفتيها، \nوحتى رسول الله ﷺ مقلهاش مثلا إن دي غيبة، لأ، مادام الإنسان بيطلب فتوى و ذكر بعض سلبيات الطرف التاني إللي ليها علاقة بالفتوى يبقى مفيش غيبة،\nأما بقى لو الإنسان ذكر عيوب وسلبيات ملهاش علاقة بالفتوى فكده هيدخل في الغيبة\nالمهم،\nبعد ما رسول الله ﷺ جاوب هند بنت عتبة انتبه على إللي بتسأل دي وبتقول أبو سفيان رجل شحيح، فعرف إنها هند فقال لها:\nوَإِنَّكَ لَهُنْدُ بِنْتُ عُتْبَةَ؟!\nفقالت: نعم، هند بنت عتبة، فاعفُ عمَّا سلف، عفا الله عنك.\nطبعا الموقف مش بسيط خالص\nإللي يشوف الموقف العام يقول إن هند جاية تبايع رسول الله ﷺ عشان تهرب من القتل لأن رسول الله ﷺ أمر بقتلها، \nوهي دلوقتي بين إيدين رسول الله ﷺ، بكلمة واحدة رقبتها تطير،\nتخيلوا إحساس رسول الله ﷺ كان إيه لما افتكر إللي عملته هند في عمه حمزة وعداءها المتواصل للإسلام،\nطبعا الموقف مش سهل نهائي، ومع ذلك عفا عنها رسول الله ﷺ ومعلقش حتى بكلمة عتاب على إللي عملته في حمزة وتقبل إسلامها بكل بساطة، ﷺ \nأكمل رسول الله ﷺ بيعته وقال:\n\"وَلا تَزْنِين\"\nفاستمرت هند في اعتراضاتها وقالت: يا رسول الله! وهل تزني الحرة؟!\nيعني هي مستغربة إزاي امرأة حرة تقع في فعل الفاحشة دي، حتى في رواية ولكنها رواية 《ضعيفة》 بتقول فيها :\n\"كنا نستحي في الجاهلية فكيف بالإسلام؟\"\nلكن بصفة عامة كان موضوع الزنا عند العرب شديد وكان إللي بيقع فيه هم الإماء.\n☆أنا بصراحة مش عارفة هند لو كانت عايشة في زماننا دلوقتي وشافت إن الزنا بقى من علامات الحرية عند بعض النساء كانت هتقول إيه\nالمهم، أكمل رسول الله ﷺ كلامه وقال:\n\" وَلا تَقْتُلْنَ أَوْلاَدَكُنَّ\"\nفقالت هند: قد ربيناهم صغارًا، وقتلتهم كبارًا في بدر\nقلنا إن ابنها كان قُتل في بدر، فهي بتقول لرسول الله ﷺ مش احنا إللي قتلناهم، احنا ربيناهم وانتم إللي قتلتوهم لما كبروا\nبتعلق على كل حاجة رضي الله عنها\nفي رواية من الروايات بتقول إن عمر بن الخطاب رضي الله عنه قعد يضحك لما سمع هند بتقول كده\nومع إن رسول الله ﷺ كان ممكن يرد عليها ويقول لها:\nوهو احنا قتلناهم ليه في بدر، همّ مش كانوا بيحاربونا وبيفتنونا عن ديننا وقهرونا وعذبونا وأخدوا أموالنا وديارنا\nوكان هيبقى معاه حق لو قال كده لأن فعلا ده إللي حصل، لكن رسول الله ﷺ تبسم وكمل كلامه عادي جدا،\nوسبحان مقلب القلوب،\nهند بنت عتبة حسُن إسلامها، و زي ما كانت بتحمس المشركين ضد المسلمين بقت بتخرج مع جيوش المسلمين تحمسهم ضد الكفار،\nوكان من أشهر مواقفها يوم معركة اليرموك، \nكانت بتشجِّع المسلمين على القتال في سبيل الله، وكان عدد المسلمين ساعتها ستة وثلاثين ألف، وعدد الرومان مائتين وأربعين ألف،\nفبسبب موقف العفو ده من رسول الله ﷺ تحولت لشخصية تانية خالص، وبقت جندي من جنود الإسلام، رضي الله عنها\n☆فاكريييين لما كان رسول الله ﷺ راجع من الطائف بعد ما أهل الطائف قذفوه بالحجارة وشتموه وقعد رسول الله ﷺ يدعو ربنا ساعتها،\nوربنا أرسل له ملك الجبال وقال له لو شئت هطبق عليهم الجبلين وهم في النص ويهلكوا جميعا\nرد فعل رسول الله ﷺ ساعتها كان إيه\nقال رسول الله ﷺ بكل هدوء ورحمة وأخلاق راقية:\nلا...بل أرجو أن يُخرج الله عز وجل من أصلابهم من يعبد الله وحده\nيعني لو الناس دي كانوا مشركين لعل أبنائهم يؤمنوا، وفعلا ده إللي حصل\nالزمن بين كلام رسول الله ﷺ إللي قاله ده وبين فتح مكة كان إحدى عشر عام،\nبعد ال11سنة دول أسلمت هند بنت عتبة بن ربيعة إللي أبوها كان كافر وكان من إللي بيؤذوا رسول الله ﷺ،\nوأسلم خالد بن الوليد بن المغيرة وأبوه كافر، وأسلم عكرمة بن أبي جهل، \nوأسلم صفوان بن أمية بن خلف، وأسلم عمرو بن العاص بن وائل وغيرهم وغيرهم من إللي أباءهم كانوا معاندين لرسول الله ﷺ،\nتخيلوا عشان يتحقق لرسول الله ﷺ إللي كان عايزه وهو رسول الله قعد 11سنة، \nفما بالكم بينا احنا محتاجين كم سنة عشان نقدر نحول قلوب الناس كده\nرسول الله ﷺ عفى عن الناس إللي أساءت له لما جاءوا معتذرين، ولم ينتقم لنفسه،\nفكانت النتيجة زي ماحنا شوفنا في مواقف كتير على مدار حياته ﷺ كلهم تقريبا دخلوا في الإسلام،\nوعلى فكرة دي حاجة مش خاصة برسول الله ﷺ بس، يعني الإحسان والعفو عن المسيء ده احنا كمان نقدر نعملها،\nربنا بيقول:\n\" ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ فَإِذَا الَّذِي بَيْنَكَ وَبَيْنَهُ عَدَاوَةٌ كَأَنَّهُ وَلِيٌّ حَمِيمٌ\"\nكلهم تحولوا لأولياء وجنود للإسلام بعد ما شافوا أخلاق رسول الله ﷺ وبعد ما عفى عنهم\nهند قالت لرسول الله ﷺ :\n\" يا رَسولَ اللَّهِ! واللَّهِ، ما كانَ علَى ظَهْرِ الأرْضِ أهْلُ خِبَاءٍ أحَبَّ إلَيَّ أنْ يَذِلُّوا مِن أهْلِ خِبَائِكَ، \nوما أصْبَحَ اليومَ علَى ظَهْرِ الأرْضِ أهْلُ خِبَاءٍ أحَبَّ إلَيَّ أنْ يَعِزُّوا مِن أهْلِ خِبَائِكَ\"\nيعني بتحلف لرسول الله ﷺ إن أكتر حد كانت تحب تشوفه مذلول هوّ وأهل بيته هو رسول الله ﷺ وأهل بيته،\nلكن دلوقتي بعد ما أسلمت بقت أكتر حد تحب تشوفه عزيز هو رسول الله ﷺ وأهل بيته،\nعداوة عشرين سنة انتهت في لحظات، مين يقدر عليها دلوقتي دي، عشان كده الصحابة كانوا أطهر الناس قلوبا\nوشوفوا كمان الموقف ده من رسول الله ﷺ، \nيوم فتح مكة جاءه رجل عايز يكلمه فالرجل واقف ترعدُ فرائصُهُ،\nيعني واقف بيرتعش من شدة الخوف من رسول الله ﷺ ،\nفرسول الله ﷺ قال له:\n\"هوِّن عليكَ ، فإنِّي لستُ بملِكٍ ، إنَّما أَنا ابنُ امرأةٍ تأكُلُ القَديدَ\"\nيعني بيقول له اهدأ متخافش أنا مش مَلِك زي الملوك الجبابرة إللي الناس بتخاف منهم ومِن أذاهم،\nأنا ابن امرأة فقيرة كانت بتاكل اللحم المملح المجفف في الشمس، يعني احنا زي بعض وحتى معندناش رفاهية الملوك وأبناء الملوك،\nورسول الله ﷺ قال له إنه ابن امرأة بالذات لأن كان من عادة المتكبرين إنهم بيأنفوا ويتكبروا إنهم يفتكروا حقيقة إنهم مولودين من امرأة،\nفرسول الله ﷺ قاله كده عشان يُهدّأه ويُؤنسه، \nكان ﷺ أحسنَ الناسِ خُلقًا، وأكثرهم تَّواضُع وأرفقُ النَّاسِ بالناس، كان بيطبّق إللي ربنا بيأمره بيه، ربنا قال له:\n\" وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ\"\nوهو ده معنى إن رسول الله ﷺ كان قرآنا يمشي على الارض، محتاجين نتعلم من أخلاقه ﷺ ونعمل زيه وده هدف مهم من أهداف إننا نعرف سيرته ﷺ\nالحياة في مكة بعد الفتح كانت هادئة وجميلة وكلها إيمان،\nكان بلال يؤذن للصلوات الخمس، \nويجتمع العشرة آلاف إللي هو جيش رسول الله ﷺ ويصلوا خلف رسول الله ﷺ،\nطبعا منظر مهيب جدا وأهل مكة شايفين العبادة الصحيحة لله، مش إللي كانوا بيعملوه السنين إللي فاتت دي كلها،\nأجواء إيمانية رائعة مهما وصفناها مش هنقدر نوفّيها حقها فعلا\nفي وسط ما كانت مكة بتستمتع بالهدوء والاسترخاء إلإيماني ده، كان في توتر في مكان قريب من مكة هيؤدي لأحداث كبيرة خلال الأيام الجاية،\nإيه الأحداث إللي هتحصل بعد كده\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 197, "l": "الجزء 171 | احداث السنه الثامنه من الهجرة | هوزان ومالك بن عوف", "u": "https://www.facebook.com/groups/710210019782034/permalink/836544503815251/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وواحد_وسبعون\n#أحداث_السنة_الثامنة_من_الهجرة\n#هوازِن_ومالك_بن_عوف\nكنا واقفين المرة إللي فاتت عند التوتر إللي كان حاصل في مكان قريب من مكة، \nالمكان إللي كان حاصل فيه توتر ده هو المكان إللي تسكنه قبيلة هَوَازِن، ليه بقى التوتر ده\nشوفوا،\nفتح مكة بصفة عامة دفع كثير من أهل الجزيرة العربية للتفكير في الإسلام، لكنه في نفس الوقت خلّى بعض القبائل  تاخد موقف مُعادي من الإسلام؛ لأنها حست إن نمو الدولة الإسلامية معناه القضاء على نفوذ القبائل دي،\nفبدأت القبائل دي تستعد عشان تحارب دولة الإسلام، \nوكان من أخطر القبائل دي هي قبيلة هَوَازِن \nمحتاجين نرجع بالزمن شوية عشان نفهم إيه موضوع قبيلة هوازن ده وعلاقتها بقريش،\nالعرب يا جماعة بينقسموا بصفة عامة إلى قسمين رئيسيين:   عدنَانِيِّين وقَحْطَانِيين، \nالعدنانيون دول بينقسموا إلى فرعين: رَبِيعة، و مُضَر،\nيعني ربيعة ده زي رئيس عيلة كده وييجي أبناؤه وأحفاده وأحفاد أحفاده، و مُضَر نفس الموضوع، ماشي كده\nفرع مُضَر ينقسم إلى: إِليَاس و عَيْلاَن، \nقبيلة قريش جاية من فرع إلياس، وقبيلة هوازن جاية من فرع عَيْلاَن،\nوكل ما الأنساب بعدت عن بعض زادت الحزازيات بين القبائل، ده أصلا بيحصل بينهم تنافسات وصراعات بين بطون القبيلة الواحدة بسبب العصبية القبيلية، زي ما كان بيحصل بين بني هاشم وبني مخزوم، والأوس والخزرج، فما بالكم بالقبائل البعيدة عن بعض في النسب\nفدلوقتي رسول الله ﷺ جاي برسالة الإسلام من قبيلة قريش، \nفكانت القبائل البعيدة عن قريش بتفكّر في الإسلام بصورة أكثر تَحفُّظًّا عن القبائل القريبة من قريش،\nوهنلاقي إن أواخر القبائل إللي دخلت في الإسلام هي أبعد القبائل عن قريش، والقبائل دي كانت من أشد القبائل قسوة على المسلمين،\nزي مثلا قبيلة قُضَاعة إللي كانت قتلت أربعة عشر رجلا من الصحابة وعرفنا قصتهم وإللي رسول الله ﷺ أرسل لهم عمرو بن العاص في سرية،\nالمهم يعني إن قبائل عَيْلاَن كانت تُنافس قبائل إلياس إللي منها قريش، وقبائل عيلان دي كثيرة لكن أشهر وأهم ثلاثة قبائل من عَيْلاَن ثلاثة هم: \n《غَطَفَان، وبنو سُلَيم، وهوازن》\nواخدين بالكم من غطفان وبنو سليم، غطفان دي إللي كان بيعاني منها المسلمين وزعيمهم الأحمق المطاع، وحاصروا المسلمين في الأحزاب، \nوكل شوية يجهزوا جيش عشان يحاربوا المسلمين ورسول الله ﷺ يرسل لهم سرية\nوبنو سليم همّ كمان كانوا عاملين مشاكل مع المسلمين من بعد غزوة بدر، وحتى رسول الله ﷺ خرج لهم بنفسه في غزوة، فده يفسر لنا العداء إللي كان بين غطفان وبنو سليم وبين المسلمين،\nوهمّ دلوقتي جاءوا وأسلموا، لكن واضح إن إسلامهم كان إسلام المضطر بعد ما شافوا قوة المسلمين وانبهروا بيها وعرفوا إن ملهمش طاقة بالمسلمين فآثروا السلامة وعدم الوقوف في وجه المسلمين،\nوعلى فكرة رسول الله ﷺ كان عارف موضوع إسلام غطفان وبني سليم ده، وواخد باله منهم، \nوهنشوفه بعدين حتى بعدين إزاي كان بيتألّف قلوبهم\nالشاهد بقى من الكلام ده إن في فرعين رئيسيين مهمين جداً من عيلان أسلما مضطرين وأعلنا الهزيمة أمام الرسول القرشي محمد ﷺ،\nومتبقاش غير قبيلة هوازن فقط، فهي إللي لسه رافعة راية عَيْلاَن\nوكانت انتصارات رسول الله ﷺ المتكررة بتمثل خطر كبير على هوازن،والموضوع زاد جداً بعد فتح مكة؛ لأن منازل هوازن قريبة جداً من مكة، يعني هي في الشمال الشرقي من مكة، \nومن وجهة نظرهم فهمّ مش مستبعدين أبداً إن الدور هييجي عليهم سواء دلوقتي أو بعدين\nطيب خلونا كده نعرف مين هي قبيلة هوازن والوضع الداخلي بتاعها إيه\nقبيلة هوازن تنقسم داخلها لقبائل كثيرة جداً، \nلكن أشهر قبائل هوازن ثلاث: \n◇بنو نَصر.\n◇بنو سعد: \nبنو سعد دول همّ إللي كان منهم حليمة السعدية إللي أرضعت رسول الله ﷺ.\n◇القبيلة الثالثة خطيرة جداً ومشهورة وهي قبيلة: 《ثقيف》\nوكانت بتعيش في مدينة الطائف في الجنوب الشرقي لمكة المكرمة، واستقرت فيها من زمان،\nلكن التجمع الرئيسي لهوازن كان في الشمال الشرقي لمكة،\nفقبيلة ثقيف من أهم القبائل العربية مطلقاً ومن أقوى القبائل العربية،\nومدينة الطائف هي المدينة الثانية في الجزيرة العربية بعد مكة؛ وحتى ربنا أخبر عن الكفار قولهم:\n\" لَوْلا نُزِّلَ هَذَا الْقُرْآنُ عَلَى رَجُلٍ مِنَ الْقَرْيَتَيْنِ عَظِيمٍ \"\nالقريتين هما مكة والطائف، والرجلين المقصودين في الآية هما الوليد بن المغيرة أبو خالد في مكة،\nوعروة بن مسعود الثقفي في الطائف، إللي كان اتكلم مع رسول الله ﷺ في صلح الحديبية لو تفتكروا،\nواحنا اتكلمنا عن صفات الطائف بالتفصيل في الجزء السابع والعشرين لما رسول الله ﷺ اختارها هي بالذات عشان يدعوا الناس فيها، فمش هعيد الكلام بقى\nفاللي يهمنا نعرفه دلوقتي إن ثقيف كانت بتشعر بالمساواة دائماً مع قريش، لأ وكمان كانت بتحس بالتفوق على قريش عسكرياً واقتصادياً وعددياً\nفأرض الطائف كانت جيدة جداً والتجارة فيها كانت تجارة رائدة،\nلكن الفرق بينها وبين قريش إن قريش كانت بترعى البيت الحرام المُعظم عند العرب، فده إللي كان مخلي قريش أعلى درجة من قبيلة ثقيف،\nوطبعا الكلام ده كمان يفسر لنا معاملة أهل الطائف السيئة لرسول الله ﷺ لما راح يدعوهم في السنة العاشرة من البعثة،\nويفسر لنا ليه مفيش ولا واحد ثقفي منهم أسلم، وحتى بعدين كان أعداد قليلة جدا همّ إللي أسلموا من ثقيف، وتأخر إسلام أهل الطائف لحد السنة التاسعة من الهجرة زي ما هنشوف إن شاء الله،\nفالوضع بين هوازن وبين قريش أصلا متوتر لوحده وفي بينهم تنافس وحزازيات، \nفما بالكم بقى دلوقتي لما واحد من قريش بقى هو الزعيم وبيحاول يفرض سيطرته على القبائل، رد فعل هوازن هيكون إيه\nأكيد الموضوع مش هيعدي بسهولة وهتحصل مشاكل جامدة\n☆خدوا بالكم إن رسول الله ﷺ معملهمش حاجة، هوازن هي  إللي خمنت مع نفسها كده إن رسول الله ﷺ هيجيب الجيش بتاعه ويكتسح هوازن، وإنه عايز يسيطر على كل حاجة\nولعل السبب في الفكرة إللي كانت عند هوازن دي هو الشخصية إللي ظهرت في بني نصر قبل فتح مكة على طول وكان اسمه :\n《مالك بن عَوْف النصري》\nمالك بن عوف ده كان شاب لم يبلغ الثلاثين من عمره، لكن كان عنده صفات قيادية متميزة... عنده علم كبير جداً بالخطط العسكرية وبالفنون القتالية، \nوكان خطيباً مفوّهاً عنده قدرة كبيرة جداً على التأثير على الناس، وكان يتميز بقدرته الرهيبة على الحشد وتجميع الطوائف المختلفة لأداء مهمة معينة،\nكانت عنده طاقات هائلة فعلا، لكن للأسف كل طاقاته دي  كانت موظفة في الشر\nبدأ مالك بن عوف يجمّع كل فروع هوازن تحت راية واحدة،\nوده حدث فريد في تاريخ هوازن؛\nلأن عادة العرب في الوقت ده إنهم عايشين حياة التفرق حتى في بطون القبيلة الواحدة،\nوقبيلة هوازن بفروعها الكتيرة دي مكنتش مختلفة عن باقي العرب، فكانت عايشة بنفس التفرق ده،\nوهي في زمنها كله لم تتوحد في كيان سياسي اقتصادي عسكري واحد،\nفدي أول مرة تقريباً إللي تتجمع فيها بطون بني نَصر وبني سعد وثقيف تحت راية واحدة على يد مالك بن عوف، \nومع إنه من بني نصر، ومعروف إن ثقيف هي أكبر وأعز وأعظم قبيلة من قبائل هوازن لكن مع ذلك قبلت ثقيف إنها تبقى تحت راية مالك بن عوف النصري\nفكل ده بيعرفنا مدى كفاءة مالك بن عوف كقائد\nجمع مالك بن عوف من قبائل هوازن أكثر من خمسة وعشرين ألف مقاتل، \nوالرقم ده هو أكبر رقم تجمع في معركة واحدة في تاريخ العرب كلهم، جيش كبير جدا\nاستغل مالك بن عوف النّزعة القبلية عشان يجمع الأعداد دي، يعني احنا من هوازن ومحمد من قريش،\nمع إن رسول الله ﷺ لم يسعَ أبدا لتجميع القرشيين ضد القبائل العربية الأخرى، بالعكس ده قريش كانت هي العدو الأكبر لرسول الله ﷺ \nلكن ده كان تفكير مالك بن عوف وعلى الأساس ده بدأ يحفز الناس ويقنعهم،\nوخصوصا إنهم أصلا اتربوا على إن عز القبيلة مُقدم على كل شيء...مُقدم على الحق وعلى العدل وعلى القِيم، \nزي بالضبط كده في زماننا دلوقتي فكرة القومية إللي ناس كتير بيتبنوها وبينادوا بيها، \nيعني بيقدموا مصلحة القوم أو الوطن أو العنصر بغض النظر عن الحق، \nيعني لو قرر الوطن أو القوم الدخول في حرب ظالمة فأنا معه؛ لأن مصلحة الوطن هي الأهم ومُقدمة على الحق والعدل\nفلو شافوا إن مصلحة القوم أو الوطن تتعارض مع قانون شرعي أو عُرف دولي أو قاعدة أخلاقية يترك القانون الشرعي أو العرف الدولي أو القاعدة الأخلاقية وتُقدَّم مصلحة القوم أو مصلحة الوطن،\nوالكلام ده ولا له أي وزن عند رب العالمين سبحانه وتعالى، شوفوا ربنا بيقول إيه:\n\" قُلْ إِنْ كَانَ آبَاؤُكُمْ وَأَبْنَاؤُكُمْ وَإِخْوَانُكُمْ وَأَزْوَاجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَالٌ اقْتَرَفْتُمُوهَا وَتِجَارَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَاكِنُ تَرْضَوْنَهَا أَحَبَّ إِلَيْكُمْ مِنَ اللَّهِ وَرَسُولِهِ وَجِهَادٍ فِي سَبِيلِهِ فَتَرَبَّصُوا حَتَّى يَأْتِيَ اللَّهُ بِأَمْرِهِ وَاللَّهُ لا يَهْدِي الْقَوْمَ الْفَاسِقِينَ\"\nفي الآية دي ربنا بيوضح لنا إن تقديم الأهل والعشيرة، إللي همّ 《القوم》، وتقديم المساكن إللي هي 《الوطن》 على أمر الدين هو نوع من الفسق،\nوإللي بيعمل كده يستنى بقى العقاب من ربنا، والعقاب مخوّف جداً على فكرة، حتى ربنا أخفى العقاب ده ولم يُعيّنه لزيادة الرهبة والخوف في النفوس\nومش معنى الكلام إن حب القوم أو الوطن نقطة مرفوضة في الإسلام\nلأ، حب الأهل والعشيرة مطلوب، لكن بشرط إن الحب ده ميكونش على حساب الدين والحق والعدل\nالوضع بقى عند مالك بن عوف كان عصبية قبلية، فهو على الرغم من إنه يعلم علم اليقين إن القرآن حق وإن رسول الله ﷺ صادق إلا أنه ضحى بالحق والدين في مقابل إنه يُعلي الراية القومية الهَوَازَانية في منتهى الوضوح\nودي كانت أول نقطة سلبية في مالك بن عوف: \n◇يدعو إلى قومية وقبلِية بغض النظر عن مواطن الحق والعدل\n◇النقطة السلبية التانية هي:\n إنه بيستخدم البلاغة وحُسن البيان في خداع الناس، يعني بيضحك على الناس بكلامه\nكان بيوهم الناس بحاجات بخلاف الواقع ويَغرر بيهم،\nوقف مالك بن عوف يخطب في الناس ويقول لهم:\n\"إن محمداً لم يُقاتل قط قبل هذه المرة، وإنما كان يَلقى قوماً أغماراً لا علم لهم بالحرب فيُنصر عليهم\"\nيعني بيقول لهم إن رسول الله ﷺ ميعرفش أي حاجة عن الحروب ومدخلش في ولا حرب قبل كده،\nولكنه كان بيقابل شوية ناس كده ميعرفوش حاجة عن الحروب فكان بينتصر عليهم مش عشان هو قوي، \nلأ، ده عشان إللي كان بيواجههم همّ إللي ضعفاء، أما احنا بقى لو قاتلناه فاحنا هنشيله من على وش الأرض\nوسبحان الله الناس صدقته تخيلوا\nهو واضح إنهم كانوا شعب ساذج ميعرفوش حاجة عن العالم حواليهم عشان يصدقوا واحد زي مالك بن عوف وهو بيزيّف الحقائق وبينكر إنجازات رسول الله ﷺ \nأو ممكن يكونوا حتى عارفين عادي، وعارفين كمان إن مالك بن عوف بيخدعهم، \nبس مش مهم مادام مالك بن عوف هو إللي قال لهم الكلام ده فخلاص بقى يبقى هو الصح،\nواحنا معاك يا مالك، واعمل إللي انت عايزه يا مالك وباقي الكلام إللي انتم عارفينه بقى\nثواني كده يا جماعة قبل ما ننخدع احنا كمان بكلام مالك بن عوف خلونا كده نشوف إنجازات رسول الله ﷺ وهل هو فعلا كان بيقاتل أغماراً لا علم لهم بالحرب\n◇هل قريش إللي اتهزمت من أيام في عُقر دارها أو حتى قبل كده في بدر والأحزاب لا علم لها بالحرب\n◇هل غطفان إللي اكتُسِحَت في ديارها فخضعت وأطاعت وسلّمت وأسلَمت لا علم لها بالحرب\n◇هل اليهود في بني قينقاع وبني النُّضير وبني قُرَيظة وكمان في خيبر لم يكن لهم علم بالحرب\n◇ هل الرومان وأعوان الرومان من نصارى العرب بأعدادهم المهولة وبأسلحتهم المتقدمة وتاريخ طويل في الحروب وخبرة فائقة لم يكن لهم علم بالحرب\nالعيب مش على مالك بن العوف إللي بيزيّف الحقائق الواضحة وبيخدع الناس بشوية كلام متزوّق\nالعيب على الناس إللي صدقته وحطّت راسها في الرمل ورضيت إنها تشوف الدنيا بعيون مالك بن عوف مش بعنيها هي،\nوكما قال أحدهم:\n《إن شعباً لا يُدرِك أحوالَ الدنيا حوله لجَدِيرٌ أن يُضْحَك عليه...لجَدِيرٌ أن يُسخَر منه...لجَدِيرٌ أن يُهزم ويُذَل》\nفالناس اختارت إنها تمشي ورا مالك بن عوف فكان لازم هيدفعوا ثمن اختيارهم ده\nتتوقعوا إن مالك بن عوف خدع قومه بس بالكلام؟\nأبدا، ده خدعهم وضيّع أموالهم وكان مستبد برأيه ومش بيسمع لكلام حد من الناصحين وبيستغل مشاعرهم، كان ممثل عاطفي كبير مقولكوش\nأنا بتكلم عن مالك بن عوف يا جماعة عشان محدش يفهمني صح\nإن شاء الله المرة الجاية هنعرف تفاصيل الحاجات إللي عملها"}, {"n": 198, "l": "الجزء 172 | احداث السنه الثامنه من الهجرة | الطريق إلى حُنين", "u": "https://www.facebook.com/groups/710210019782034/permalink/836544727148562/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_واثنان_وسبعون\n#أحداث_السنة_الثامنة_من_الهجرة\n#الطريق_إلى_حُنَيْن\nاتكلمنا المرة إللي فاتت عن مالك بن عوف وقلنا إنه كان عنده \nصفات قيادية متميزة وإنه استطاع يجمع كل قبائل هوازن المُشركة تحت راية واحدة،\nوقلنا إن أول سلبية عنده كانت إنه بيدعو إلى قومية وقبلِية بغض النظر عن مواطن الحق والعدل،\nوالسلبية التانية كانت إنه بيستخدم البلاغة وحُسن البيان في خداع الناس،\n◇النقطة السلبية الثالثة في مالك بن عوف كانت إنه لم يُقِم وزناً يُذكر لشعبه، يعني شعبه ده مش مهم بالنسبة له،\nفهو معندوش أي مانع إنه يضحي بشعبه كله بكل ممتلكاته عشان يحقق مجد شخصي له\nعمل إيه مالك بن عوف؟\nأمر أن تُؤخذ النساء والأطفال والأنعام والأموال وكل ممتلكات شعب هوازن لأرض القتال ويخلوها خلف الجيش،\nطيب ليه أمر بالخطة الخارقة للذكاء دي\nقال عشان يحفّز الجيش على القتال\nيعني بيقولهم خدوا بالكم انتم لو انهزمتم المسلمين هياخدوا ممتلكاتكم ونساءكم، فلازم تقاتلوا باستماتة،\nيعني هو مفكرش في احتمالية الهزيمة، مع إنها احتمال وارِد جدا وممكن يحصل، وطبعا مفكرش في مصير النساء والأطفال وأموال المقاتلين دول،\nهو عايزهم يضحوا بكل شيء عشان يحقق النصر، فمفيش عنده مشكلة إن الشعب كله يدفع ثمن تحقيق مجد شخصي  له\n☆ممكن حد يقول مش يمكن فعلا مالك بن عوف يهمه مصلحة شعبه وعايزهم ينتصروا فعلا فبيحفزهم ومش بيفكر في مجده الشخصي واحنا إللي ظالمينه\nشوفوا،\nالطبيعي في الشخص إللي بيكون عايز مصلحة إللي حواليه إنه بيستشير أهل الخبرة ويدرس الموضوع كويس ويشوف الأصلح إيه وبيعمله \nمالك بن عوف معملش كده، بالعكس بقى ده كان ديكتاتور مُستبد برأيه ومش بيسمع لحد، زي فرعون كده:\n\"مَا أُرِيكُمْ إِلَّا مَا أَرَى وَمَا أَهْدِيكُمْ إِلَّا سَبِيلَ الرَّشَادِ\"\nودي كانت النقطة السلبية الرابعة في مالك بن عوف\nبعض الخبراء العسكريين في هوازن زي دُرَيْد بن الصُّمّة حاولوا يبعدوا مالك بن عوف عن قرار أخذ النساء والأطفال والأنعام والأموال لأرض المعركة،\nلكنه أصر إصرار عجيب على قراره\nو دُرَيْد بن الصُّمّة ده مكنش رجل عادي، ده كان عمره فوق المائة سنة وكان رأيه حكيم و خاض حروب كتيرة وعنده خبرة واسعة،\nفلما خرج مع الجيش وسمع أصوات الأغنام والبعير وبكاء الأطفال سأل عن الأصوات دي وكان ساعتها أعمى، فالناس قالوا له إن مالك أمر بإخراج النساء والأطفال وأخذ الأموال لأرض المعركة، \nفقال لهم نادوا لي مالك بن عوف، فجاءه مالك وسأله دُرَيْد بن الصُّمّة عشان يتأكد منه إذا كان فعلا أمر بإخراج البعير والنساء والأطفال،\nفقال له مالك إنه فعلا أمر بكده، فدُرَيْد سأله ليه عمل كده فقال له مالك:\nأردتُ أن أجعلَ خلف كل رجلٍ أهله ومالَه ليُقاتِل عنهم\nفهنا دُرَيْد بن الصُّمّة غضب جدا وقال لمالك:\nراعي ضَأْنٍ والله\nهل يرد المُنهزمَ شيء؟\nإنها إنْ كانت لك لم يَنفعك إلا رجل بسيفه ورمحه، وإن كانت عليك فُضِحْت في أهلك ومالِك\nيعني دُرَيْد بيقول لمالك انت آخرك تكون راعي غنم، انت متنفعش للقيادة العسكرية، هو المقاتل لما بينهزم في حاجة بتوقفه، ده ما بيصدق يهرب!\nلو النصر كان من نصيبك فمش هينفعك غير المقاتل بسيفه ورمحه، ولو حصلت الهزيمة أهلك ومالك كلهم هيضيعوا منك وهتبقى فضيحة لك،\nفقاله يرجع النساء والأطفال والأموال ويخليهم في مكان آمن \nلكن مالك بن عوف لم يسمع له، ولم يأخذ بمشورته، ومكنش شايف غير رأيه هو بس، \nيبقى ده واحد فارق معاه مصلحة شعبه ولّا مش بيفكر غير في نفسه وإنه يحقق الانتصار وخلاص بغض النظر عن التمن إللي ممكن الناس تدفعه؟\nومع ذلك دريد لم ييئس، واستمر معاه في الحوار وسأله:\n ما فعلت كَعْب وكِلاَب؟\n☆كَعْب وكِلاَب دول أفضل بطون هوازن عسكرياً وفيهم العدد والعدة،\nقال له مالك : لم يشهد منهم أحد\nيعني محدش منهم جاء يشارك في الحرب،\nفقال دريد وهو عنده يقين إن رأيه صح: \nغاب الحَدّ والجِدّ، لو كان يومَ عَلاءٍ ورِفْعة لم تغِب عنه كعب وكلاب\nيعني بيقوله لو المعركة دي كان هيبقى فيها نصر وعِز لهوازن مكنش كعب وكلاب غابوا عنها،\nوقاله يخلي النساء والأطفال والأموال في مكان آمن بعيد عن أرض المعركة عشان لو حصلت الهزيمة يكونوا في أمان،\nلكن مالك بن عوف مقتنعش بكلام دريد وفضل مصمم على رأيه، وقال لدريد: والله لا أفعل ولا أغيّر أمراً صنعته، إنك قد كَبِرت وكَبُر عقلك\nيعني بيقوله هو ده القرار إللي أخدته ومش هرجع فيه، انت خلاص كبرت في السن وخرّفت،\nيعني مالك بن عوف مش يقول مثلا أسباب مُقنعة عشان يفضل متمسك برأيه كده،\nلأ، ده هو مش عايز يرجع في كلامه عشان كبريائه وكرامته ميسمحلوش بكده\nوهي دي شخصية الديكتاتور، شخصية لا تقبل أبداً أي رأي معارض لرأيها ولو على سبيل الاقتراح أو المشورة؛\nلأن الشورى عنده بتبقى طاعنة للكبرياء والكرامة،\nوبالتالي فالدكتاتوريين مش عايزين الخير إلا إذا جاء منسوباً لهم\n◇النقطة السلبية الخامسة في مالك بن عوف كانت: التلاعب بعواطف الناس بصورة مسرحية تؤثر على العوام، \nفكان بيستغل الأزمات إللي بتحصل لصالحه\nشوفوا حصل إيه\nبعد ما دُريد كلّمه ولقاه مصمم على رأيه وشاف إنه مفيش منه فايدة بدأ يوجه الكلام لهوازن يمكن يسمعوا كلامه،\nوخصوصا إنهم عارفينه من زمان وعارفين خبرته في الحرب وعارفين رأيه الحكيم، قال لهم دريد:\n\"والله ما هذا لكم برأي، هذا فاضحُكم في عورتِكم ومُمَكّن منكم عدوكم ولاحِقٌ بحصن ثقيف وتارككم فانصرِفُوا واتركُوه\"\nيعني بيقول لهم رأي مالك ده غلط وهيوديكم في داهية وهيضيّع أموالكم ونساءكم، \nو في الآخر هيهرب لحصن ثقيف لما تحصل الكارثة ويسيبكم تواجهوا مصيركم ولا هينفعكم ساعتها.\n☆دريد عارف إن القادة إللي من النوعية دي بيتركوا شعوبهم في الأزمات وبيلحقوا نفسهم ويهربوا للمكان الآمن،\nسواء بقى المكان ده كان حصون وقلاع أو مُدن جديدة يبنوها لنفسهم، أو يسيبوا البلد ويروحوا بلد تانية\nفهنا مالك بن عوف شاف إن الناس ميّالة لرأي دريد بن الصمة وإنهم كده ممكن يقفوا ضد قراره ويرجعوا النساء والأطفال والأنعام،\nفوقف يخطب في الناس كأنه ممثل كبير على مسرح درامي\nقال لهم: والله لتطيعُونني يا معشر هوازن أو لأتكِئَن على هذا السيف حتى يخرج من ظهري\nيعني هتسمعوا كلامي وتعملوا إللي بقولكم عليه ولّا أموّت نفسي\nفلأن الشعب مخدوع بيه أصلا من البداية فقالوا الرأي رأي مالك، والراجل هيموّت نفسه كده، وهو يا عيني مش عايز الزعامة ولا الرياسة، بس رضي بيها عشان مصلحتنا\nومشيوا ورا قرار مالك بن عوف وكل واحد فيهم جاب نسائه وأطفاله وكل ما يملك من أموال وبعير وممتلكات،\nوتوجهوا إلى سهل أَوْطاس القريب من حُنين،\nوبدأ فعلاً في تنظيم الجيش وبدأ يعمل كمائن على جانبي سهل حنين في المكان إللي هيعدي منه المسلمون،\nواحنا قلنا المرة إللي فاتت إن مالك بن عوف كان عنده عبقرية عسكرية وعنده قدرة كبيرة على تنظيم الصفوف وترتيب الحروب، فبدأ بقى يرتب الجيش في صفوف متوازية ورا بعض كده \n | | | |\nيعني وضع الخيل في المقدمة، وبعدين الرّجَّالة إللي بيقاتلوا على رجلهم خلف الخيول،\nوفي الآخر وضع النساء فوق الإبل خلف الرجال؛ عشان يُوهم المسلمين أن في أعداد كبيرة فوق الجمال من الرجال، فيتزايد العدد إلى أضعاف، وبالتالي يبقى في تأثير سلبي على نفسية المسلمين،\nوبعدين صَفّ بعد ده كله الغنم وصَفّ في الآخر النَّعم، يعني كان ترتيب عسكري في غاية الإتقان\nحتى أنس بن مالك رضي الله عنه لما جاء مع جيش المسليمن وشاف جيش هوازن قال عن الجيش:\n\"فجاء المشركون بأحسن صفوفٍ رأيت\"\nيعني تقسيمة جيش هوازن كانت أحسن تقسيمة شافها،\nوإللي عمل التقسيمة دي كان مالك بن عوف، \nفهو كان زي ما قلنا شخصية قيادية بمعنى الكلمة، له القدرة على تجميع الناس وتحميسهم،\nوله القدرة على إقناع الناس بوجهة نظره سواء عن طريق العقل أو طريق العاطفة،\nوله القدرة على وضع الخطط العسكرية وإتقانها، \nولولا السلبيات إللي قلنا عليها لكان اتحسب من القواد المعدودين في تاريخ الجزيرة العربية\n☆طيب يعني الراجل عنده قدرات حلوة أهه \nأيوة لكن العبرة بالنهاية يا جماعة هتكون إيه، وهنشوف إن شاء الله الكارثة إللي مالك هيحط جيش هوازن فيها\nده كان استعداد جيش هوازن والأحداث إللي حصلت عندهم، نرجع بقى احنا لرسول الله ﷺ ونشوف هيتعامل مع الموضوع إزاي\nطبعا زي ماحنا متعودين من رسول الله ﷺ إن بيكون حاطط عيون في أماكن المختلفة عشان تجيب له الأخبار،\nفوصل لرسول الله ﷺ الأخبار إن هوازن بتجهز جيش لقتال المسلمين،\nوهوازن كانت بتجهز الجيش ده من أول ما عرفوا إن رسول الله ﷺ خارج من المدينة في جيش، هو ساعتها مكنش حد عارف رسول الله ﷺ رايح فين بالضبط،\nفهوازن فكّروا إن رسول الله ﷺ خارج بجيشه عشان يقاتلهم فبدأوا يجمعوا نفسهم عشان يستعدوا لقتال رسول الله ﷺ،\nفي الوقت إللي جمعوا نفسهم تحت قيادة مالك بن عوف زي ما قلنا كان رسول الله ﷺ فتح مكة وحصلت الأحداث إللي قلنا عليها قبل كده، ودخلنا دلوقتي في شهر شوال،\nأرسل رسول الله ﷺ الصحابي عبد الله بن أبي حَدْرد لهوازن عشان يعرف أخبارهم وعددهم أد إيه ويتأكد هل هوزان فعلا جهزت جيش لحرب المسلمين ولّا هتحارب حد تاني،\nرجع عبد الله بن أبي حَدْرد لرسول الله ﷺ ومعاه الخبر إن هوازن جاءوا كلهم ومعاهم نسائهم والأنعام بتاعتهم،\nفتبسم رسول الله ﷺ وقال:\n\"تلكَ غَنيمةُ المسلِمينَ غدًا إن شاءَ اللَّهُ\"\nيعني هننتصر عليهم وهناخد الحاجات بتاعتهم دي غنيمة\nبدأ بقى رسول الله ﷺ يجهز للقاء هوازن:\n◇أول حاجة عملها هو إنه قرر الخروج للقتال في مكان متوسط بين هوازن ومكة، وإنه ميستناش جيش هوزان في مكة، ليييه\nلأنه لو استنى في مكة وجاء مالك بن عوف بجيشه لقتال المسلمين في مكة ممكن جدا أهل مكة يتعاونوا معاه ضد رسول الله ﷺ والصحابة؛\nلأن أهل مكة كانوا لسه مشركين وعلى جاهلية من شهر واحد بس، ولسه الإيمان لم يستقر في قلوبهم وهتشوفوا أصلا إللي بعضهم هيعمله لما تحصل المعركة،\nفكانت وجهة نظر رسول الله ﷺ في إنه يخرج لقتال مالك بن عوف صحيحة،\n تخيلوا لو حصل تعاون بين هوازن وبين أهل مكة ضد المسلمين هتبقى كارثة فعلا وتبقى حرب داخل مكة وحرب خارجها\nفقرر رسول الله ﷺ إنه يخرج للقتال في مكان مكشوف بعيدا عن مكة.\n ◇ثانيا:\n قرر رسول الله ﷺ إنه يخرج بكامل طاقته العسكرية،\nيعني هياخد معاه العشرة آلاف مقاتل إللي فتح بيهم مكة؛ لأن أعداد هوازن كبير جدا زي ما شوفنا.\n◇ثالثاً:\n أخذ رسول الله ﷺ معاه في الجيش بتاعه المسلمين أهل مكة إللي أسلموا بعد الفتح وإللي بقى اسمهم الطلقاء زي ما شرحنا قبل كده، وكان عددهم ألفين،\nو القرار ده بيُظهر فيه حكمة رسول الله ﷺ جدا؛\nلأن في احتمال إنه لو تركهم في مكة ممكن ينقلبوا ويرجعوا للكفر مرة تانية وينفصلوا بمكة عن الدولة الإسلامية، وخصوصا لو تعرض المسلمون للهزيمة من جيش هوازن\n☆شايفين الفرق بين رسول الله ﷺ وبين مالك بن عوف، رسول الله ﷺ وهو رسول الله بيفكر في احتمال الهزيمة وبيعمل لها حساب،\nلكن مالك بن عوف مكنش بيفكر في الاحتمال ده أصلا\nالمهم،\nكمان لما الطلقاء يخرجوا مع جيش رسول الله ﷺ ده فيه دلالة على إن رسول الله ﷺ يقربهم ويثق بهم، ودي حاجة تثبت أقدامهم أكثر في الإسلام،\nده غير إن هيبقى في غنائم فأراد رسول الله ﷺ إنه يستغل موضوع الغنائم في تأليف قلوبهم،\nفبقى عدد الجيش كله اثنا عشر ألف وده أكبر عدد يتجمع في تاريخ المسلمين لحد اللحظة دي\n◇رابع حاجة عملها رسول الله ﷺ في التجهيز للجيش إنه  لم يكتفِ بسلاح الجيش الإسلامي إللي فتح به مكة، ولكنه عمل صفقة عسكرية كبيرة لتقوية الجيش الإسلامي،\nمع إن أسلحة الجيش الإسلامي كانت قوية أصلا، بدليل انبهار أبي سفيان لما شاف الجيش وهو معدّي قصاده،\nلكن رسول الله ﷺ كان عايز زيادة في السلاح من حيث الجودة والعدد،\nيعني رسول الله ﷺ بيعلمنا بطريقة عملية تطوير الإمكانيات بتاعتنا، زي ما ربنا قال بالضبط:\n\"وَأَعِدُّوا لَهُمْ مَا اسْتَطَعْتُمْ مِنْ قُوَّةٍ وَمِنْ رِبَاطِ الْخَيْلِ\"\nهو لقى إن في استطاعته دلوقتي إنه يجيب سلاح أكثر وأفضل و يحدّث إمكانيات الجيش فعمل كده،\nراح رسول الله ﷺ لصفوان بن أمية وطلب منه سلاح؛ لأنه كان زي ما بنقول في زماننا دلوقتي بيشتغل تاجر سلاح، وكان ساعتها لسه على الكفر،\nفصفوان سأل رسول الله ﷺ:\nأغصباً يا محمد؟\nيعني انت عايزني أديك السلاح بالغصب ولّا إيه، فقال له رسول الله ﷺ:\nبل عَاريةٌ مَضْمونة\nيعني بيقوله أنا هستعيرها منك بالإيجار وأضمن لك إن لو ضاع منها حاجة هعوضك عنها.\n☆شوفوا سبحان الله مع إن رسول الله ﷺ هو الزعيم المنتصر، وصفوان بن أمية هو أحد القادة المهزومين، لكنه ﷺ كان عادل في كل أموره، وعمره ماكان يستحل مال عدو بأي صورة من الصور، ﷺ \n◇خامسا:\nرسول الله ﷺ اهتم جداً بالحراسة الليلية للجيش الإسلامي؛ عشان محدش يهجم على المسلمين فجأة.\nدي كانت أهم النقط إللي رسول الله ﷺ اهتم بيها في تجهيز جيش المسلمين\nخرج الجيش من مكة في السادس من شوال سنة ثمانية من الهجرة متوجهين لوادي حُنَين وكان العدد اثنا عشر ألفا زي ما قلنا من شوية،\nوكان في الجيش بعض المشركين اصطحبهم رسول الله ﷺ معاه عشان يحملوا أسلحة المسلمين، زي صفوان بن أمية و نَوْفل بن الحارث،\n☆هنا ممكن حد يسأل سؤال ويقول:\nهو ليه رسول الله ﷺ رضي هنا إنه يستعين في المعركة دي بمشركين، في حين إنه رفض الاستعانة قبل كده باليهود وكانوا كفار في غزوة أحد وقال : لا أستعين بمشرك\nطبعا الوضع مختلف، فقبل كده عدد المسلمين كان قليل وممكن ساعتها يُنسب النصر للمشركين بسبب قلة أعداد المسلمين وعدم استقرار دولة الإسلام،\nلكن دلوقتي مفيش حد هيقدر يقول إن المسلمين إللي عددهم اثنا عشر ألفا انتصروا بسبب الأفراد المشركين المعدودين في الجيش الإسلامي،\nفكان عادي إن رسول الله ﷺ ياخدهم معاه في الجيش، وهم مش هياخدوا من الغنيمة ولكن رسول الله ﷺ هيعطيهم أجر على عملهم\nوطبعا احنا اتكلمنا في الجزء الثاني والسبعين عن حكم الاستعانة بالمشركين بالتفصيل، فممكن ترجعوا له لو حبيتم\nلما كان الجيش ماشي في الطريق لوادي حنين مرُّوا على شجرة عظيمة لونها أخضر، فقال المسلمون الجُدد من الطلقاء:\n\"يا رسول الله! اجْعَلْ لَنَا ذَاتَ أَنْوَاطٍ كما لهم ذَاتَ أَنْوَاطٍ\"\nيعني بيقولوا لرسول الله ﷺ إن المشركين كان عندهم شجرة كبيرة معينة معروفة باسم 《ذَاتَ أَنْوَاطٍ》 بيعلقوا عليها أسلحتهم ويتبركوا بالشجرة دي وبيذبحوا عندها الذبائح،\nفاحنا كمان عايزين شجرة نعلق عليها سيوفنا ونتبرك بيها ونذبح عندها الذبائح،\nهو انتم لكم أن تتخيلوا هَوْل المفاجأة إللي وقعت على رسول الله ﷺ لما سمع كلامهم\n إللي هو يا جماعة ده رسول الله ﷺ أصلا ربنا أرسله عشان يزيل الشرك،\nوانتم خارجين تقاتلوا المشركين إللي بيعبدوا مع الله إلها آخر وبيتبركوا بأمور شركية مفيهاش أي بركة،\nإزاي بقى عايزين رسول الله ﷺ يعمل لكم حاجة كلها شرك\nكان إيه بقى رد فعل رسول الله ﷺ على الكارثة دي\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 199, "l": "الجزء 173 | احداث السنه الثامنه من الهجرة | تحريم  زواج المتعه | الهزيمه في حنين", "u": "https://www.facebook.com/groups/710210019782034/permalink/836545030481865/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاثة_وسبعون\n#أحداث_السنة_الثامنة_من_الهجرة\n#تحريم_زواج_المتعة\n#الهزيمة_في_حنين\nاتكلمنا المرة إللي فاتت عن خروج جيش المسلمين من مكة في اتجاه وادي حنين لقتال هوازن،\nوقلنا إن بعض المسلمين الجُدد من الطلقاء لما عدّوا على شجرة خضراء عظيمة افتكروا شجرة ذات أنواط إللي العرب كانوا بيلعقوا عليها أسلحتهم وبيطوفوا حولها وبيعظموها، فقالوا لرسول الله ﷺ:\n\"يا رسول الله! اجْعَلْ لَنَا ذَاتَ أَنْوَاطٍ كما لهم ذَاتَ أَنْوَاطٍ\"\nفقال لهم رسول الله ﷺ:\n\" الله أكبر، إنها السُّنَنْ! قُلتم والذي نفسي بيده كما قالت بنو إسرائيل لموسى:\n\"اجْعَلْ لَنَا إِلَهًا كَمَا لَهُمْ آلِهَةٌ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ\"\nلتركبن سَنَنَ مَن كانَ قبلكم\"\nيعني رسول الله ﷺ غضب من كلامهم وقال الله أكبر، وكان من عادته إنه لما بيغضب بيقول الله أكبر أو سبحان الله،\nوقال لهم إن عبادة الأشجار والأحجار والتأَسّي بالآباء والأسلاف هي السُّنّة المعروفة عند الناس،\nفرسول الله ﷺ قالهم والله انتم قلتم زي ما قالت بنو إسرائيل لموسى اجْعَلْ لَنَا إِلَهًا كَمَا لَهُمْ آلِهَةٌ،\nولو تفتكروا في قصص الأنبياء لما اتكلمنا عن هلاك فرعون وبنو إسرائيل شافوا بعينهم إزاي ربنا أهلكه بالغرق ونجاهم،\nفبعد ما خرجوا من البحر عدّوا على ناس بيعبدوا الاصنام فطلبوا من موسى إن يكون عندهم إله يعبدوه زي ما الناس دي عندهم إله يعبدوه،\nوكأن ربنا مش موجود في حساباتهم أصلا\nفالمسلمين الطلقاء عاشوا زمن طويييل جدا بيعبدوا الأصنام، فلسه مش فاهمين مين هو ربنا، وإن الإسلام جاء لإلغاء الشركيات دي كلها، \nزي بني إسرائيل كده لما قعدوا في مصر أربعمائة سنة وكانوا شايفين أهل مصر بيعبدوا الأصنام، ومكنوش فاهمين طبيعة الإله الخالق إللي أرسل موسى عليه السلام لهم\n☆وخدوا بالكم هنا إن العبرة بالحقائق والمعاني مش بالألفاظ،\nيعني المسلمين الطلقاء قالوا اجعل لنا ذات أنواط،\nوبني إسرائيل قالوا اجعل لنا إلها،\nالألفاظ والكلمات مختلفة لكن المعنى واحد وهو إنهم طلبوا حاجة فيها شرك بالله،\nزي مثلا لو تفتكروا في قصص الأنبياء كل الأقوام إللي كانوا بيعبدوا الأصنام كانوا بيقولوا لأنبيائهم:\n\" إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ\"\nيعني احنا لقينا آباءنا وأجدادنا بيعملوا كده فاحنا هنعمل زيهم،\nففي ناس في عصرنا دلوقتي ماشيين بنفس المنطق ده،\nلما نيجي نقولهم حاجة في الدين يقولوا طيب ما أباءنا وأمهاتنا مكنوش بيعملوا كده، فاحنا هنبقى زيهم\nفالألفاظ مختلفة عن الموجودة في القرآن لكن المعنى واحد وهو التمسك باللي كان عليه الآباء والأجداد حتى لو كان باطل\nالمهم بقى رسول الله ﷺ قالهم بعد كده كلمة خطيرة\n\"قال: \"لتركبُن سَنَنَ مَن كانَ قبلكم\"\nيعني هييجي يوم من الأيام وهتقلدوا اليهود والنصارى، وحصل فعلا وواقع وشايفينه زي ما رسول الله ﷺ قال بالضبط\nواقع في زماننا دلوقتي الغُلو في الصالحين والغُلو في الأنبياء، وعُبدت القبور وعُظّمت وبُني عليها القِباب والمساجد،\nوالناس بقت تعتقد في الأبراج والحظ وكل ده من الشركيات،\nومحصلش الاتباع لليهود والنصارى في العقيدة وبس ده كمان في نواحي تانية من الحياة،\nسواء الاحتفالات أو اللبس أو الشكل والهيئة وقصّات الشعر،\nيعني مثلا من كم سنة كان لما الواحد يبقى في لبسه حتة مقطوعة مكنش يرضى لبسها حتى لو كانت قطعة صغيرة،\nلكن لما الغرب طلّعوا موضة لبس المقطع بقى المسلمين بيتسارعوا في لبس المقطع إلا من رحم الله وعَصَمه من اتباع الموضة دي،\nوخدوا إعفاء اللحية ولبس البنطلون القصير إللي على السنة مثال برده، كان الناس بيسخروا من إللي بيعملهم وبيلتزم بيهم،\nلكن لما طِلعوا موضة من عند الغرب بقى الشباب بيسارعوا لتقليدهم ومفيش أي اعتراض عليهم\nوقيسوا بقى على كده\nفاللي عايز ينجوا يا جماعة يتبع منهج رسول الله ﷺ والصحابة، ويبعد تماما عن اتباع اليهود والنصارى والموضات إللي بيطلعوها لنا\n☆ملحوظة مهمة:\n أنا بتكلم في أمور العقيدة والحاجات إللي بتخالف ديننا ومينفعش إننا نقلد فيها الكفار من يهود أو نصارى أو غيرهم،\nلكن أي حاجة فيها فايدة لينا و《مش بتخالف عقيدتنا》 فمفيش مشكلة إننا ناخدها منهم، زي الموبايلات مثلا وزي السيارات وغيرها من الحاجات المفيدة لينا،\nولو تفتكروا في غزوة خيبر رسول الله ﷺ أخذ من الغنائم أسلحة مكنتش موجودة عند المسلمين واستعملها في القتال ضد اليهود أنفسهم\nوبالمناسبة دي صحيح في حديث مشهور بيقول :\n\" الحكمة ضالة المؤمن أنّى وجدها فهو أحق الناس بها\"\n الحديث ده بقى ضعيف جدا لا يصح نسبته لرسول الله ﷺ \nهو معنى الحديث صحيح وفي شواهد في الشرع بتؤكد المعنى ده، لكن الحديث نفسه بالألفاظ دي وألفاظ تانية مقاربة له لا يصح عن رسول الله ﷺ\nقبل ما نرجع للجيش  إللي كان في طريقه لوادي حنين ونشوف حصل معاه إيه،\nفي نقطة مهمة عايزة أقولها حصلت بعد ما رسول الله ﷺ دخل مكة وكنت نسيت أقولها معلش \nالنقطة دي هي: تحريم زواج المتعة.\nوزواج المتعة معناه:\nإن رجل وامرأة يتفقوا على الزواج لحد وقت معين مقابل مبلغ معين من المال، وأول ما الوقت ده يخلص يحصل فُرقة بين الرجل والمرأة،\nيعني يحددوا شهر أو اثنين أو سنة أو سنتين يفضلوا متزوجين فيهم في مقابل إن الرجل يعطي المرأة مبلغ من المال وبعد ما المدة دي تخلص كل واحد يروح لحاله،\nوالنفقة في الزواج ده لا تجب على الزوج،\nيعني الزوج ميصرفش على مراته إللي متزوجها زواج المتعة،\nوخلال الفترة الزمنية لزواج المُتعة ده لو الزوج مات المرأة لا تَرِث منه، \nوزواج المتعة ده كان مباح في أول الإسلام وبعدين تم تحريمه نهائيا بعد فتح مكة،\nوفي علماء بيقولوا إن زواج المتعة تمت إباحته وتحريمه  مرتين،\nيعني زواج المتعة كان مُباح في أول الإسلام قبل غزوة خيبر، وبعدين تم تحريمه في غزوة خيبر لما نزل تحريم أكل الحُمُر الأهلية،\nوبعدين ربنا أباح زواج المتعة مرة تانية يوم فتح مكة وبعدها بثلاثة أيام تم تحريم زواج المتعة تحريم مؤبد إلى يوم القيامة، واستقر تحريمه،\nلكن الراجح والصحيح يا جماعة على حسب الدليل إن الكلام ده محصلش، يعني زواج المتعة اتحرم مرة واحدة فقط وده كان عام الفتح، \nقال رسول الله ﷺ:\n\" أيُّها النَّاسُ، إنِّي قدْ كُنْتُ أذِنْتُ لَكُمْ في الاسْتِمْتاعِ مِنَ النِّساءِ، وإنَّ اللَّهَ قدْ حَرَّمَ ذلكَ إلى يَومِ القِيامَةِ،\n فمَن كانَ عِنْدَهُ منهنَّ شيءٌ فَلْيُخَلِّ سَبِيلَهُ، ولا تَأْخُذُوا ممَّا آتَيْتُمُوهُنَّ شيئًا\"\nيعني بيقول إن زواج المتعة كان مباح لكن دلوقتي خلاص انتهى الحكم ده وبقى زواج المتعة محرم إلى يوم القيامة، وإللي متزوج من امرأة زواج مُتعة خلاص ينهي الزواج ده ومياخدش المال إللي كان أعطاه لها في بداية الزواج،\nومع إن كلام رسول الله ﷺ صحيح صريح في تحريم زواج المتعة إلا إن في بعض الطوائف بتحلّله وبيعتبروه قُربة الواحد بيتقرب بها إلى الله، زي طائفة الشيعة وده طبعا مخالف لكلام رسول الله ﷺ\nعندنا بقى هنا سؤالين\n◇السؤال الأول:\nإيه السبب في إباحة زواج المتعة \nإللي يجاوبنا على السؤال ده هو عبد الله بن مسعود، قال:\n\" كُنَّا نَغْزُو مع النبيِّ ﷺ وليسَ معنَا نِسَاءٌ، فَقُلْنَا: ألَا نَخْتَصِي؟ فَنَهَانَا عن ذلكَ، \nفَرَخَّصَ لَنَا بَعْدَ ذلكَ أنْ نَتَزَوَّجَ المَرْأَةَ بالثَّوْبِ ثُمَّ قَرَأَ:\n \"يَا أيُّها الَّذِينَ آمَنُوا لا تُحَرِّمُوا طَيِّبَاتِ ما أحَلَّ اللَّهُ لَكُمْ\"\nيعني عبد الله بن مسعود بيقول إنهم كانوا بيخرجوا للغزو مع رسول الله ﷺ ومكنش معاهم زوجاتهم،\nفسألوا رسول الله ﷺ إنهم ينزعوا الخصْيتينِ وذلك حتَّى لا يشعُروا بِشهوةِ النِّساءِ فلا يحتاجوا إلى الزَّواجِ،\nفنهاهُم رسول الله ﷺ عَنِ الخِصاءِ، ورخَّصَ لهم أنْ يتَزوَّجوا المرأةَ بِالثَّوبِ،\nيعني يتراضوا بينهم على مهر معين زي مثلا الثياب، وقرأ عليهم رسول الله ﷺ الآية إللي ربنا بينهاهم فيها عن تحريم الطيبات إللي أحلها لهم زي التزوج من النساء وغيرها.\n◇السؤال التاني:\nإيه الحكمة من تحريم زواج المتعة\nالأصل في الزواج الاستدامة والاستقرار،\nيعني عشان الزواج يبقى مستقر ويحصل فيه الإنجاب وتكوين أسرة، لازم النية في الزواج إنه يكون دائم عشان العيشة تستقيم،\nبعكس زواج المتعة إللي هو لفترة معينة عشان رغبة مؤقتة،\nفمفيش عِشْرة ومفيش ذرية،\nوشريعة الإسلام أصلا بتحرص على الزواج المستقر وإنجاب الذرية\nده غير إن الأولاد كده هيكونوا مشردين، ويتربوا بعيد عن أبوهم،\nيعني الرجل لما يتزوج امرأة زواج متعة وبعدين يسافر ويتركها وهي تحمل وتخلّف، الأطفال هيعيشوا من غير أب،\nوطبعا ده له أثر سلبي عليهم، وكمان في مشقة على المرأة نفسها، \nوكمان لو المرأة دي خلفت بنت مثلا، وجاء أقارب أبوها من المحارم بعد سنين وتزوجها حد منهم زواج متعة وهي من محارمه،\nفهندخل هنا في اختلاط أنساب وكمان زواج محارم،\nده غير كده كمان هيحصل تعطيل للميراث؛ لأن الولد إللي اتولد من المتعة أبوه وإخوته مجهولين ولا يمكن تقسيم الميراث إلا لما نعرف عدد الورثة كم بالضبط،\nيعني زواج كله كوارث\nفكان من الطبيعي جدا تحريمه \n《إللي عايز تفصيل أكتر عن موضوع زواج المتعة هيلاقي الروابط في التعليقات من موقع الإسلام سؤال وجواب وموقع إسلام ويب\n》\nنرجع بقى لجيش المسلمين إللي خرج من مكة يوم ستة شوال في اتجاه وادي حُنين، همّ قعدوا في الطريق حوالي أربعة أيام، \nالليلة إللي قبل المعركة رسول الله ﷺ قال :\n\"مَن يحرسُنا اللَّيلةَ\"\nفقال واحد من الصحابة اسمه أنَسُ بنُ أبي مرثد الغَنويُّ:\n\"أَنا يا رسولَ اللَّهِ\"\n☆و أنَسُ بنُ أبي مرثد الغَنويُّ ده يا جماعة يبقى أخو مَرثد بن أبي مرثد إللي كان بيتسلل لمكة في الخفاء بعد ما هاجر هو وأبوه عشان ينقذ المسلمين المستضعفين إللي كانوا بيتعذبوا في مكة وبيشيلهم على ظهره وبيرجع بيهم للمدينة،\nوبعدين قُتل في حادثة ماء الرجيع مع عاصم بن ثابت،\nواحنا اتكلمنا عنه في الجزء الرابع والثمانين لو تفتكروا\nالمهم، \nلما أنس تطوع بإنه يحرس رسول الله ﷺ وجيش المسلمين رسول الله ﷺ أمره إنه يركب على فرس ويتوجه ناحية الشِّعب الموجود في المنطقة دي لحد ما يوصل لأعلاه،\nوالشِّعبُ هو الطَّريقُ بينَ الجَبَلَينِ، وقال له رسول الله ﷺ:\n\" لا نُغَرَّنَّ مِن قِبَلِك اللَّيلةَ\"\nيعني خليك مفتح وصاحي ومركز عشان العدو ميهجمش علينا وانت نايم ومش واخد بالك واحنا معتمدين عليك،\nفانطلق أَنَس لأعلى الشِّعب وقعد يحرس،\nفلما جاء الصبح، خرج رسول الله ﷺ للمكان إللي بيصلوا فيه فصلى ركعتين، وبعدها قال للصحابة:\nهل أحسَسْتُم فارِسَكم؟\nيعني حد شاف أنس او سمع صوته، فقال الصحابة:\n\" يا رسولَ اللهِ، ما أحسَسْناه\"\nيعني محدش فينا يعرف عنه حاجة\nفأُقيمت الصلاة،\n\"فجَعَل رسولُ اللهِ ﷺ وهو يُصلِّي يَلتَفِتُ إلى الشِّعبِ\"\nيعني بقى ينظر بطرف عينه ناحية الطريق إلى الجبل، فلما خلّص صلاته قال:\n\"أبشِروا فقد جاءَكُم فارسُكُم\"\nفالصحابة قعدوا ينظروا من خلال الشجر الموجود في الشِّعب فلقوا أنس جاي على فرسه،\nوجاء ووقف عند رسول الله ﷺ وقال له إنه راح في المكان إللي رسول الله ﷺ أمره يروحه وقعد يدوّر على جانبي طريق الجبل ونواحيه عشان يشوف إذا كان في حد مستخبي ولّا حاجة؛ فملقاش حد،\nفقال له رسول الله ﷺ:\n\" هَل نزَلْتَ اللَّيلة؟\"\nيعني هل نزلت من على الفرس بتاعك الليلة دي،\nفقال له أنس إنه فضل قاعد على الفرس طول الليل ومكنش بينزل من عليه إلا لو عشان يصلي أو يقضي حاجته من بول أو غائط،\nفقال له رسول الله ﷺ:\n\" قد أوجَبْتَ فلا عليكَ أن لا تَعملَ بعدَها\"\nيعني كده وَجبت لك الجنة بسبب الحراسة بتاعتك دي، وانت مش محتاج تعمل نوافل بعد كده خلاص بسبب حراستك لينا طول الليل\nوصل جيش المسلمين لوادي حُنين في العاشر من شوال، يعني بعد ما خرجوا من مكة بأربعة أيام،\nو ده يعتبر مدة زمنية طويلة؛ لأن المسافة من مكة لوادي حنين حوالي سبعة وعشرين كيلو بس،\nفي حين إن جيش المسلمين جاء من المدينة لمكة في عشر أيام، والمسافة بين مكة والمدينة خمسمائة كيلو، يعني كانوا بيمشوا بمعدل خمسين كيلو في اليوم،\nفإزاي بقى قعدوا أربع أيام في مسافة سبعة وعشرين كيلو مع إنهم كان المفروض يقطعوا المسافة دي في نص يوم \nلأ ومش كده وبس ده أول ما وصلوا لوادي حنين راحوا داخلين على طول من غير ما يشوفوا في كمائن ولّا لأ، ومن غير ما يرتبوا المعركة هتبقى إزاي،\nاندفعوا ودخلوا المعركة على طول بدون أي تفكير و تَأَني،\nوده خطأ عسكري كبير جدا وقعوا فيه،\n مع إن الجيش ده كان فيه خالد بن الوليد العبقري وفيه عمرو بن العاص وأبو عبيدة بن الجراح وغيرهم من القادة العسكريين الكبار،\nوفوق كل دول القائد رسول الله ﷺ،إللي كان بيقود الجيش بحكمته العسكرية المعروفة، وبدقته في إدارة الأمور،\nوطبعا بسبب الخطأ ده حصلت الكارثة\nجيش المسلمين أول ما دخل وادي حُنين مفيش دقائق إلا واتعرض لهجوم شديد من الكمائن إللي كان مالك بن عوف مجهزها\nالكمائن دي أمطرت جيش المسلمين بالسهام والرماح من كل مكان وثارت خيول هوازن في وجوه المسلمين،\nوخرجت فِرق هوازن من هنا وهناك، وأُحيط بالمسلمين من كل مكان، وفي لحظات انهارت عزائم المسلمين ومعظم الجيش بدأ يهرب من أرض المعركة \nمفيش مقاومة ولا تفكير، كله بدأ يهرب هروب عشوائي، \nتخيلوا إن متبقاش في أرض المعركة حول رسول الله ﷺ غير عشرة بس\nعشرة من اثنا عشر ألف، وكان من العشرة دول أبو بكر وعمر والعباس، وأبو سفيان بن الحارث ابن عم رسول الله ﷺ إللي كان رسول الله ﷺ رافض إنه يقابله وهو في طريقه لفتح مكة واتكلمنا عنه في الجزء المائة واثنين وستين،\nفي الوقت الحَرِج ده أثبت صدقه وانتماءه للإسلام وصِدق دفاعه عن رسول الله ﷺ بعد ما كان بيهجوه،\nكارثة أشد من كارثة فرار المسلمين في أُحد؛ لأن في أحد  خالف بعض رجال الجيش خالفوا الأمر وبعضهم ثبت، وبعضهم قاتل حتى الشهادة،\nلكن هنا في حنين كله هرب ما عدا عشرة\nليه حصلت كل الأحداث دي، ويا ترى هيخرج المسلمون من الأزمة دي إزاي،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
